window.JBC_LEVEL_B_87=[{"candidate_id":"ATLBC-CAND-0001","name_en":"Ai","name_ko":"아이","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AI","ko":"아이. Ai\n“폐허”라는 뜻이다. (1) 가나안 사람의 왕성 가운데 하나이다(수 10:1; 창 12:8; 13:3). 여호수아가 패배한 현장이며 후에 승리한 현장이었다. 이스라엘이 점령한 두 번째 가나안 성읍이다(수 7:2-5; 8:1-29). 후에 베냐민 사람이 다시 세워 거주했다(스 2:28; 느 7:32; 11:31). 벧엘 동쪽, “벧아웬 곁”에 있었다. 이 옛 성읍의 터로 가장 유력한 곳은 벧엘 동쪽 2마일의 하이얀이다. 요단 골짜기에서 벧엘까지 뻗은 가파르고 험한 골짜기인 와디 수웨이닛 위쪽에 있었다.\n\n(2) 암몬 영토의 성읍이다(렘 49:3). 일부는 이 낱말의 바른 읽기가 아르(사 15:1)라고 생각했다.","source_sha256":"46c51f5c5db742622294fdac4f565cc9c519defb7339b9a6288cf0aa8663a00f","citation_candidates":[{"source":"Josh. 10:1","passage":"jos-10","verse":1,"ref":"jos-10:1","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Gen. 12:8","passage":"gen-12","verse":8,"ref":"gen-12:8","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Josh. 7:2-5","passage":"jos-7","verse":2,"ref":"jos-7:2","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Ezra 2:28","passage":"ezr-2","verse":28,"ref":"ezr-2:28","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Neh. 7:32","passage":"neh-7","verse":32,"ref":"neh-7:32","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Jer. 49:3","passage":"jer-49","verse":3,"ref":"jer-49:3","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Isa. 15:1","passage":"isa-15","verse":1,"ref":"isa-15:1","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"가나안 사람의 왕성 가운데 하나로, 여호수아가 한 번 패하고 후에 승리한 곳입니다."},{"candidate_id":"ATLBC-CAND-0002","name_en":"Anathoth","name_ko":"아나돗","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANATHOTH","ko":"아나돗. Anathoth\n베냐민 지파에 있는 도피성 가운데 하나의 이름이다(수 21:18). 유다 사람은 대체로 팔레스타인에서 발견한 성읍의 이름을 바꾸지 않았으므로, 이 성읍은 여신 아낫에게서 이름을 얻은 것으로 볼 수 있다. 다윗의 “삼십 용사” 가운데 한 사람인 아비에셀의 고향이며(삼하 23:27), 또 다른 용사 예후의 고향이기도 하다(대상 12:3). 그러나 무엇보다 예레미야가 태어나 평소에 살던 곳으로 유명하다(렘 1:1; 11:21-23; 29:27; 32:7-9). 산헤립의 군대에게 크게 고통을 당했고, 포로기에서 돌아온 사람은 128명뿐이었다(느 7:27; 스 2:23). 예루살렘 북쪽 약 3마일에 있었다. 주민 약 100명이 사는 작고 가난한 마을 아나타로 비정되어 있다.","source_sha256":"6f9d09da39a4d3b8017aecb5ecc22d57d0f8e2bfb990103d068f1e53dec8093b","citation_candidates":[{"source":"Josh. 21:18","passage":"jos-21","verse":18,"ref":"jos-21:18","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"2 Sam. 23:27","passage":"2sa-23","verse":27,"ref":"2sa-23:27","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"1 Chr. 12:3","passage":"1ch-12","verse":3,"ref":"1ch-12:3","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Jer. 1:1","passage":"jer-1","verse":1,"ref":"jer-1:1","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Neh. 7:27","passage":"neh-7","verse":27,"ref":"neh-7:27","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Ezra 2:23","passage":"ezr-2","verse":23,"ref":"ezr-2:23","status":"KRV_VERIFIED","exact_korean_token":"아나돗"}],"status":"READER_REFERENCE_ONLY","intro_ko":"베냐민 지파의 도피성 가운데 하나로, 후에 예레미야의 고향으로 이름이 높은 성읍입니다."},{"candidate_id":"ATLBC-CAND-0003","name_en":"Antioch","name_ko":"안디옥","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANTIOCH","ko":"안디옥. Antioch\n(1) 수리아의 오론테스 강변에 있으며, 지중해에서 약 16마일, 예루살렘에서 북쪽으로 약 300마일 떨어져 있다. 수리아의 수도였고 후에 아시아의 로마 속주의 수도가 되었다. 로마 제국의 도시 가운데 중요성에서 로마와 알렉산드리아 다음의 셋째 자리를 차지했다. “동방의 으뜸 도시”라 불렸다. 기독교가 일찍 이곳에 들어왔고(행 11:19, 21, 24), “그리스도인”이라는 이름이 이곳에서 처음 신도들에게 붙여졌다(행 11:26). 복음의 초기 역사와 긴밀히 이어져 있다(행 6:5; 11:19, 27, 28, 30; 12:25; 15:22-35; 갈 2:11-12). 이방인에게 선교사를 보내는 중심지였다. 주후 407년에 죽은 유명한 교부 크리소스토무스의 출생지이다. 현대 이름은 안타키아이며 지금은 쇠락해 가는 초라한 터키 마을이다. 빌립보처럼 로마 식민도시의 지위로 올려졌다. 이런 식민도시는 “법무관”들이 다스렸다(개정역 난외주, 행 16:20-21).\n\n(2) 비시디아 맨 북쪽에 있으며, 바울과 바나바가 첫 전도 여행 때 찾았다(행 13:14). 여기서 그들은 회당과 많은 개종자를 만났다. 복음 전도에서 큰 성공을 거두었으나 유다 사람이 격렬한 반대를 일으켜 그들은 이곳을 떠나야 했다. 돌아오는 길에 바울은 제자들을 굳게 하려고 다시 안디옥을 찾았다(행 14:21). 에베소 동쪽에 있는 지금의 얄로바치로 비정되어 있다.","source_sha256":"cf0b1bf85acfd0ca95267bb49d0a79cb76d21543a0b313278b684a56efc19422","citation_candidates":[{"source":"Acts 11:19","passage":"act-11","verse":19,"ref":"act-11:19","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 11:26","passage":"act-11","verse":26,"ref":"act-11:26","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 6:5","passage":"act-6","verse":5,"ref":"act-6:5","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Gal. 2:11","passage":"gal-2","verse":11,"ref":"gal-2:11","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 16:20","passage":"act-16","verse":20,"ref":"act-16:20","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 13:14","passage":"act-13","verse":14,"ref":"act-13:14","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 14:21","passage":"act-14","verse":21,"ref":"act-14:21","status":"KRV_VERIFIED","exact_korean_token":"안디옥"}],"status":"READER_REFERENCE_ONLY","intro_ko":"오론테스 강변의 수리아 수도로, 로마 제국에서 로마와 알렉산드리아 다음가는 성읍이며 일찍 기독교가 전해진 곳입니다."},{"candidate_id":"ATLBC-CAND-0004","name_en":"Antipatris","name_ko":"안디바드리","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANTIPATRIS","ko":"안디바드리. Antipatris\n헤롯 대왕이 세우고 아버지 안티파터를 기려 이렇게 이름 붙인 성읍이다. 가이사랴와 룻다 사이, 가이사랴에서 예루살렘으로 가는 큰 로마 도로 위에서 내륙으로 2마일 들어간 곳에 있었다. 바울은 밤에 가이사랴로 가는 길에 이곳으로 끌려왔으며(행 23:31), 가이사랴까지는 28마일이었다. 팔레스타인에서 가장 큰 샘인 아우제 샘이 솟는 지금의 라스 엘아인으로 비정된다.","source_sha256":"0288475433d491d62ad0c23cb4e22de0de570c3d170f6d9b9308bb05cfec8f17","citation_candidates":[{"source":"Acts 23:31","passage":"act-23","verse":31,"ref":"act-23:31","status":"KRV_VERIFIED","exact_korean_token":"안디바드리"}],"status":"READER_REFERENCE_ONLY","intro_ko":"헤롯 대왕이 아버지 안티파터를 기려 세운 성읍으로, 바울이 밤에 가이사랴로 압송되며 지난 곳입니다."},{"candidate_id":"ATLBC-CAND-0005","name_en":"Arad","name_ko":"아랏","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ARAD","ko":"아랏. Arad\n(1) 지금의 텔 아라드로, 가나안 사람의 성읍이며 헤브론 남쪽 약 20마일에 있다. 이스라엘이 에돔 경계에서 물러날 때 아랏 왕이 “이스라엘과 싸워 그들 가운데 몇 사람을 사로잡았다”(민 21:1; 33:40; 삿 1:16). 마침내 여호수아에게 정복되었다(12:14).\n\n(2) 브리아의 아들 가운데 하나이다(대상 8:15).","source_sha256":"7da653ae29611c100f13b4ff6ead44bbe0a0cc7fcc99b6a7ae6763c6e369521f","citation_candidates":[{"source":"Num. 21:1","passage":"num-21","verse":1,"ref":"num-21:1","status":"KRV_VERIFIED","exact_korean_token":"아랏"},{"source":"Judg. 1:16","passage":"jdg-1","verse":16,"ref":"jdg-1:16","status":"KRV_VERIFIED","exact_korean_token":"아랏"},{"source":"1 Chr. 8:15","passage":"1ch-8","verse":15,"ref":"1ch-8:15","status":"KRV_VERIFIED","exact_korean_token":"아랏"}],"status":"READER_REFERENCE_ONLY","intro_ko":"헤브론 남쪽 약 20마일의 가나안 성읍으로, 그 왕이 이스라엘과 싸워 포로를 잡았으나 후에 여호수아에게 정복되었습니다."},{"candidate_id":"ATLBC-CAND-0006","name_en":"Arimathea","name_ko":"아리마대","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ARIMATHEA","ko":"아리마대. Arimathea\n“유대인의 동네”(눅 23:51)로 불렸으며, 우리 주님이 그 무덤에 장사되신 요셉의 출생지이다(마 27:57, 60; 요 19:38). 아마 에브라임의 라마다임, 곧 사무엘의 출생지(삼상 1:1, 19)와 같은 곳일 것이다. 다른 이들은 이곳을 단의 라믈레 또는 베냐민의 라마(참조, 마 2:18)로 비정한다.","source_sha256":"4fbc073852dffc5b58c0cbc119530a748b26d955ff1292f7f591bb00cf84f722","citation_candidates":[{"source":"Luke 23:51","passage":"luk-23","verse":51,"ref":"luk-23:51","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"Matt. 27:57","passage":"mat-27","verse":57,"ref":"mat-27:57","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"John 19:38","passage":"jhn-19","verse":38,"ref":"jhn-19:38","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"1 Sam. 1:1","passage":"1sa-1","verse":1,"ref":"1sa-1:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 2:18","passage":"mat-2","verse":18,"ref":"mat-2:18","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"요셉의 고향으로 “유대인의 동네”라 불린 곳이며, 이 요셉의 무덤에 우리 주님이 장사되었습니다."},{"candidate_id":"ATLBC-CAND-0008","name_en":"Ashkelon","name_ko":"아스글론","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ASHKELON","ko":"아스글론. Ashkelon\n= 아스글론 = 아스칼론. 블레셋의 다섯 성읍 가운데 하나이다(수 13:3; 삼상 6:17). 가사 북쪽 12마일의 지중해 해안에 있었다. 이집트 카르나크의 비문에 히브리 사람을 압제한 람세스 2세에게 점령된 곳으로 언급된다. 사사 시대에 유다 지파의 소유가 되었으나(삿 1:18) 곧 블레셋 사람에게 다시 빼앗겼고(삼하 1:20), 이들은 알렉산드로스 대왕 때에야 마침내 쫓겨났다. 삼손은 딤나에서 이곳으로 내려가 삼십 명을 죽이고 그들의 노획물을 가져갔다. 예언자들은 이곳의 멸망을 예언했다(렘 25:20; 47:5, 7). 중세에는 사라센 사람과 십자군 사이의 피비린내 나는 숱한 전투의 무대가 되어 유명한 곳이 되었다. 사자왕 리처드에게 포위되어 점령되었고, 그는 “지금도 서 있는 성벽과 탑 안에서 궁정을 열었다.” 텔 엘아마르나 점토판(애굽 항목 참조) 가운데에는 “기병대장이요 왕의 발의 티끌” 야다야가 이집트의 “대왕”에게 아스칼론에서 보낸 편지 또는 공문서가 있다. 지금은 아스칼란이라 불린다.","source_sha256":"b89946c311bdf6d67038f3ba012be2c94aa58bd3b6f8f8c1c40a40ad9affb53f","citation_candidates":[{"source":"Josh. 13:3","passage":"jos-13","verse":3,"ref":"jos-13:3","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"1 Sam. 6:17","passage":"1sa-6","verse":17,"ref":"1sa-6:17","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"Judg. 1:18","passage":"jdg-1","verse":18,"ref":"jdg-1:18","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"2 Sam. 1:20","passage":"2sa-1","verse":20,"ref":"2sa-1:20","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"Jer. 25:20","passage":"jer-25","verse":20,"ref":"jer-25:20","status":"KRV_VERIFIED","exact_korean_token":"아스글론"}],"status":"READER_REFERENCE_ONLY","intro_ko":"블레셋의 다섯 성읍 가운데 하나로, 가사 북쪽 12마일의 지중해 해안에 있었습니다."},{"candidate_id":"ATLBC-CAND-0009","name_en":"Athens","name_ko":"아덴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ATHENS","ko":"아덴. Athens\n앗티카의 수도이며 고대 세계에서 가장 유명한 도시로, 그리스 역사의 황금기에 그리스 문학과 예술의 중심지였다. 주민들은 새로운 것을 좋아했고(행 17:21) 신을 숭배하는 열심이 남달랐다. 로마의 풍자 시인은 “아덴에서는 사람을 찾기보다 신을 찾기가 더 쉽다”고 비꼬았다.\n\n바울은 제2차 전도 여행 때 이 도시를 방문하여(행 17:15; 비교 살전 3:1) 아레오바고에서 유명한 연설을 했다(17:22-31). 바울이 거기서 “알지 못하는[정확히는 ‘어떤’] 신에게”라 새겨 바쳐졌다고 말한 제단(23절)은 같은 비문을 가진 여러 제단 가운데 하나였을 것이다. 이는 아덴에 전염병이 돌 때 양과 염소 떼를 거리에 풀어 놓았다가 그것들이 눕는 자리에서 “해당 신에게” 제물로 바치던 관습에서 비롯되었다고 추정된다.","source_sha256":"d2f2834d7b2cac1ef33db1d6a0dc62c1182d015061c599e1c043864f64cc5d75","citation_candidates":[{"source":"Acts 17:21","passage":"act-17","verse":21,"ref":"act-17:21","status":"KRV_VERIFIED","exact_korean_token":"아덴"},{"source":"Acts 17:15","passage":"act-17","verse":15,"ref":"act-17:15","status":"KRV_VERIFIED","exact_korean_token":"아덴"},{"source":"1 Thess. 3:1","passage":"1th-3","verse":1,"ref":"1th-3:1","status":"KRV_VERIFIED","exact_korean_token":"아덴"}],"status":"READER_REFERENCE_ONLY","intro_ko":"앗티카의 수도로 고대 세계에서 가장 유명한 도시였으며, 바울이 제2차 전도 여행 때 방문한 곳입니다."},{"candidate_id":"ATLBC-CAND-0011","name_en":"Bethany","name_ko":"베다니","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETHANY","ko":"베다니. Bethany\n“대추야자의 집”이라는 뜻이다. (1) 개정역은 요 1:28에서 가장 오래된 사본의 근거에 따라 벳바라 대신 이 낱말을 쓴다. 요단 동쪽의 한 곳의 이름이었던 듯하다.\n\n(2) 감람산 남동쪽 비탈의 마을로(막 11:1), 예루살렘에서 동쪽으로 약 2마일, 여리고로 가는 길에 있다. 그곳에 자라던 종려나무가 많아서 이런 이름을 얻었다. 나사로와 그의 누이들이 살던 곳이다. 우리 주님의 생애에서 기억할 만한 사건과 관련하여 자주 언급된다(마 21:17; 26:6; 막 11:11-12; 14:3; 눅 24:50; 요 11:1; 12:1). 지금은 엘아자리예, 곧 “나사로의 곳” 또는 단순히 라자리예라는 이름으로 알려져 있다. 멀리서 보면 이 마을은 “놀랍도록 아름답고, 은거와 안식의 완벽함이요 한적함과 사랑스러운 평화”라고 묘사되었다. 지금은 스무 가구쯤 사는 초라한 마을이다.","source_sha256":"d1ec401fd13e8530ccb1807dc5d5983a020f450e67c69c5fec14bf31b86139b4","citation_candidates":[{"source":"John 1:28","passage":"jhn-1","verse":28,"ref":"jhn-1:28","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Mark 11:1","passage":"mrk-11","verse":1,"ref":"mrk-11:1","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Matt. 21:17","passage":"mat-21","verse":17,"ref":"mat-21:17","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Mark 11:11","passage":"mrk-11","verse":11,"ref":"mrk-11:11","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Luke 24:50","passage":"luk-24","verse":50,"ref":"luk-24:50","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"John 11:1","passage":"jhn-11","verse":1,"ref":"jhn-11:1","status":"KRV_VERIFIED","exact_korean_token":"베다니"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“종려나무의 집”이라는 뜻으로, 요단 동쪽의 한 곳과 예루살렘 동쪽 약 2마일 감람산 남동쪽 비탈의 마을을 가리킵니다."},{"candidate_id":"ATLBC-CAND-0012","name_en":"Bethsaida","name_ko":"벳새다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETHSAIDA","ko":"벳새다. Bethsaida\n“고기잡이의 집”이라는 뜻이다. (1) 갈릴리의 성읍으로 디베랴 바다 서쪽의 “게네사렛 땅”에 있었다. 베드로와 안드레와 빌립의 고향이며 예수께서 자주 찾으신 곳이다(막 6:45; 요 1:44; 12:21). 게네사렛 북쪽의 만인 지금의 아인 타비가로 추정된다.\n\n(2) 그리스도께서 오천 명을 먹이신 곳 가까이의 성읍이며(눅 9:10; 비교 요 6:17; 마 14:15-21), 소경이 시력을 회복한 곳(막 8:22)으로, 호수 동쪽, 요단 강 위쪽 2마일에 있었다. 가울라니티스 지방 안에 있었고 분봉왕 빌립이 확장하여 황제의 딸의 이름을 따 “율리아스”라 불렀다. 또는 일부 추측처럼 요단이 호수로 들어가는 곳 가까이에 호수 양쪽에 걸쳐 세워진 벳새다가 하나뿐이었을 수도 있다. 지금은 폐허 엣텔이다.","source_sha256":"e88fdc913b57f1e48edc3975e90d36dd6fb5514308eb06533c21d16455477424","citation_candidates":[{"source":"Mark 6:45","passage":"mrk-6","verse":45,"ref":"mrk-6:45","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"John 1:44","passage":"jhn-1","verse":44,"ref":"jhn-1:44","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"Luke 9:10","passage":"luk-9","verse":10,"ref":"luk-9:10","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"John 6:17","passage":"jhn-6","verse":17,"ref":"jhn-6:17","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 14:15-21","passage":"mat-14","verse":15,"ref":"mat-14:15","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Mark 8:22","passage":"mrk-8","verse":22,"ref":"mrk-8:22","status":"KRV_VERIFIED","exact_korean_token":"벳새다"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“고기잡이의 집”이라는 뜻으로, 베드로와 안드레와 빌립의 고향인 갈릴리 성읍이며 예수께서 자주 찾으신 곳입니다."},{"candidate_id":"ATLBC-CAND-0013","name_en":"Beth-horon","name_ko":"벧호론","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-HORON","ko":"벧호론. Beth-horon\n“움푹한 곳의 집” 또는 “동굴의 집”이라는 뜻이다. 에브라임 영토에서 예루살렘에서 욥바로 가는 길에 있던 두 성읍 또는 마을의 이름이다(대하 8:5; 대상 7:24). “윗벧호론”과 “아랫벧호론”으로 구별된다. 서로 약 2마일 떨어져 있으며 앞의 것은 예루살렘에서 북서쪽으로 약 10마일에 있다. 두 곳 사이에 기브온에서 서쪽 평야로 내려가는 벧호론의 오르막과 내리막이 있었는데(수 10:10-11; 18:13-14), 여호수아가 아모리 다섯 왕을 이 길로 몰아냈다. 이 큰 전투는 히브리 사람이 그때까지 치른 전투 가운데 가장 중요한 것으로, 적과 처음으로 맞붙은 야전이었다. 여호와께서 무시무시한 우박으로 이스라엘을 위해 개입하셨고, 이스라엘 사람의 칼보다 우박으로 죽은 가나안 사람이 더 많았다. 벧호론은 시삭(주전 945년)이 정복지 목록에 이곳을 점령한 것으로 언급했고, 이 고개는 유다 마카비의 승리의 현장이기도 했다. (비교 출 9:19, 25; 욥 38:22-23; 시 18:12-14; 사 30:30.) 이 곳들의 현대 이름은 베이트 우르이며 엘포카, 곧 “윗”과 엘타흐타, 곧 “아랫”으로 구별된다. 아랫벧호론은 고개 기슭에, 윗벧호론은 그보다 500피트 높은 꼭대기, 기브온 서쪽에 있었다. (기브온 항목 참조.)","source_sha256":"71407f804e5b4395ff962039d93f712fd1dfaa0e3aff37b9f7afb0264415e675","citation_candidates":[{"source":"2 Chr. 8:5","passage":"2ch-8","verse":5,"ref":"2ch-8:5","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"1 Chr. 7:24","passage":"1ch-7","verse":24,"ref":"1ch-7:24","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"Josh. 10:10","passage":"jos-10","verse":10,"ref":"jos-10:10","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"Job 38:22","passage":"job-38","verse":22,"ref":"job-38:22","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Ps. 18:12-14","passage":"psa-18","verse":12,"ref":"psa-18:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Isa. 30:30","passage":"isa-30","verse":30,"ref":"isa-30:30","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"에브라임 영토에서 예루살렘과 욥바로 가는 길에 있던 윗벧호론과 아랫벧호론 두 성읍입니다."},{"candidate_id":"ATLBC-CAND-0014","name_en":"Beth-shean","name_ko":"벧스안","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-SHEAN","ko":"벧스안. Beth-shean\n“안전” 또는 “쉼의 집”이라는 뜻이다. 요단 서쪽에 있던 므낫세 지파에 속한 성읍이다(대상 7:29). 사울과 그의 아들들의 시신이 이 성벽에 매달렸다. 솔로몬 때에는 한 지역에 이 이름이 붙었다(왕상 4:12). 이 이름은 삼상 31:10, 12와 삼하 21:12에서 줄어든 형태인 벧산으로 나온다. 예루살렘에서 다메섹으로 가는 길 위에 있으며 요단 강에서 약 5마일, 게네사렛 호수 남단에서 14마일 떨어져 있다. 포로기 이후에는 스키토폴리스, 곧 “스키타이 사람의 성읍”이라 불렸는데, 스키타이 사람은 주전 640년경 남러시아 초원에서 내려와 시리아 여러 곳에 정착했다. 지금은 베이산이라 불린다.","source_sha256":"688c2f9f6880c458ae252b55b450fe3ad63c1eafacdea23b76eb5791870f4ece","citation_candidates":[{"source":"1 Chr. 7:29","passage":"1ch-7","verse":29,"ref":"1ch-7:29","status":"KRV_VERIFIED","exact_korean_token":"벧스안"},{"source":"1 Kings 4:12","passage":"1ki-4","verse":12,"ref":"1ki-4:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 31:10","passage":"1sa-31","verse":10,"ref":"1sa-31:10","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 21:12","passage":"2sa-21","verse":12,"ref":"2sa-21:12","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"요단 서쪽 므낫세 지파에 속한 성읍으로, 사울과 그의 아들들의 시신이 성벽에 매달린 곳입니다."},{"candidate_id":"ATLBC-CAND-0015","name_en":"Beth-shemesh","name_ko":"벧세메스","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-SHEMESH","ko":"벧세메스. Beth-shemesh\n“태양의 집”이라는 뜻이다. (1) 단 지파에 있던 제사장 성읍이며(수 21:16; 삼상 6:15), 유다 북쪽 경계에 있었다(수 15:10). 이스라엘 왕 여호아스와 유다 왕 아마샤가 맞붙어 아마샤가 포로가 된 곳이다(왕하 14:11, 13). 후에 블레셋 사람에게 점령되었다(대하 28:18). 유다 산지 북서쪽 비탈, 예루살렘 서쪽 14마일에 있는, 폐허가 된 아랍 마을 아인 셰므스가 지금의 이곳이다.\n\n(2) 도단과 요단 강 사이, 잇사갈 남쪽 경계 가까이에 있던 성읍으로(수 19:22), 벧산에서 남쪽으로 7.5마일에 있다. 지금의 아인 에쉬셈시예이다.\n\n(3) 납달리의 “견고한 성읍” 가운데 하나로(수 19:38), 다볼 산과 요단 강 사이에 있었다. 지금의 키르벳 셰마로, 사페드 서쪽 3마일이다. 그러나 아마 (2)와 같은 곳일 것이다.\n\n(4) 이집트에 있던 우상 신당이다(렘 43:13). 헬라인은 헬리오폴리스, 이집트 사람은 온(참조, 창 41:45)이라 불렀다.","source_sha256":"c427e0be2bdc4088d6d791f0c739bacdbbee2d47d02b174428a228086caa4572","citation_candidates":[{"source":"Josh. 21:16","passage":"jos-21","verse":16,"ref":"jos-21:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 6:15","passage":"1sa-6","verse":15,"ref":"1sa-6:15","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Josh. 15:10","passage":"jos-15","verse":10,"ref":"jos-15:10","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 14:11","passage":"2ki-14","verse":11,"ref":"2ki-14:11","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"2 Chr. 28:18","passage":"2ch-28","verse":18,"ref":"2ch-28:18","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Josh. 19:22","passage":"jos-19","verse":22,"ref":"jos-19:22","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 19:38","passage":"jos-19","verse":38,"ref":"jos-19:38","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Jer. 43:13","passage":"jer-43","verse":13,"ref":"jer-43:13","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Gen. 41:45","passage":"gen-41","verse":45,"ref":"gen-41:45","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“태양의 집”이라는 뜻으로, 유다 북쪽 경계에 있던 단 지파의 제사장 성읍입니다."},{"candidate_id":"ATLBC-CAND-0017","name_en":"Bozrah","name_ko":"보스라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BOZRAH","ko":"보스라. Bozrah\n“울타리”, “요새”라는 뜻이다. (1) 에돔 초기 왕 요밥의 성읍이다(창 36:33). 후대 예언자들이 이곳을 언급한다(사 34:6; 렘 49:13; 암 1:12; 미 2:12). 지금의 이름은 엘부세이레이다. 페트라 산악 지대에 있으며 사해 남동쪽 20마일에 있다.\n\n(2) “평지”(렘 48:24)에 있던 모압의 성읍으로, 곧 사해 동쪽의 높은 평탄한 땅에 있었다. 아마 지금의 부즈라일 것이다.","source_sha256":"0e971decbbc8b07553a662eef743d4f597acae0670c58aad45261a39537efcbb","citation_candidates":[{"source":"Gen. 36:33","passage":"gen-36","verse":33,"ref":"gen-36:33","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Isa. 34:6","passage":"isa-34","verse":6,"ref":"isa-34:6","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Jer. 49:13","passage":"jer-49","verse":13,"ref":"jer-49:13","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Amos 1:12","passage":"amo-1","verse":12,"ref":"amo-1:12","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Micah 2:12","status":"UNSUPPORTED_BOOK"},{"source":"Jer. 48:24","passage":"jer-48","verse":24,"ref":"jer-48:24","status":"KRV_VERIFIED","exact_korean_token":"보스라"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“요새”라는 뜻으로, 에돔 초기 왕 요밥의 성읍이며 예언자들이 언급한 곳입니다."},{"candidate_id":"ATLBC-CAND-0018","name_en":"Caesarea","name_ko":"가이사랴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CAESAREA","ko":"가이사랴. Caesarea\n(팔레스타인의) 지중해 해안의 성읍으로, 두로에서 이집트로 가는 큰길 위에 있고 예루살렘에서 북서쪽으로 약 70마일, 샤론 평야의 북쪽 끝에 있다. 헤롯 대왕이 옛 “스트라톤의 망대”라는 성읍 터에 세웠고(주전 10년), 카이사르 아우구스투스를 기려 이름을 붙여 가이사랴 세바스테(헬라어 세바스토스 = “아우구스투스”)라 불렸다. 로마 속주 유대의 수도로서 총독 곧 프로쿠라토르의 관저이자 로마군의 사령부가 있었다. 팔레스타인의 큰 이방인 도시로서 널찍한 인공 항구를 갖추었다. 서방 로마 도시의 방식을 따라 웅장한 건물이 많이 지어졌다. 여기서 백부장 고넬료가 베드로의 수고로 회심했으며(행 10:1, 24), 이로써 처음으로 믿음의 문이 이방인에게 열렸다. 전도자 빌립이 네 딸과 함께 여기 살았다(21:8). 사울은 예루살렘에서 도망해야 했을 때 이곳에서 고향 다소로 배를 탔고(9:30), 제2차 전도 여행에서 돌아올 때 이곳에 상륙했다(18:22). 로마로 항해하기 전에 이곳에서 이 년간 죄수로 머물렀다(행 24:27; 25:1, 4, 6, 13). 이곳에서 황제 글라우디오를 기리는 경기가 극장에서 열린 “정한 날”에 헤롯 아그립바 1세가 화려한 차림으로 사람들 앞에 나타났는데, 자기에게 바쳐지는 우상숭배적 찬사 속에서 갑자기 천사에게 맞아 죽어 가는 몸으로 실려 나갔다. 그는 “벌레에게 먹혀”(12:19-23) 할아버지 헤롯 대왕과 같은 끔찍한 병으로 죽었다. 이곳은 지금도 옛 이름 카이세리예를 지니고 있으나 황폐하다. “이 폐허의 지금 주민은 뱀, 전갈, 도마뱀, 멧돼지, 자칼이다.” 팔레스타인에서 가장 황폐한 성읍이라고 묘사된다.","source_sha256":"e35b81d4b7ba555ece4556031587c489cbb86a6bf1f8c4f1f67628ff9f376842","citation_candidates":[{"source":"Acts 10:1","passage":"act-10","verse":1,"ref":"act-10:1","status":"KRV_VERIFIED","exact_korean_token":"가이사랴"},{"source":"Acts 24:27","passage":"act-24","verse":27,"ref":"act-24:27","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"지중해 해안의 샤론 평야 북단에 헤롯 대왕이 세운 성읍으로, 로마 총독이 머문 곳입니다."},{"candidate_id":"ATLBC-CAND-0019","name_en":"Capernaum","name_ko":"가버나움","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CAPERNAUM","ko":"가버나움. Capernaum\n“나훔의 동네”라는 뜻으로, 우리 주님의 생애를 기록한 이야기에 자주 언급되는 갈릴리 성읍이다. 구약에는 나오지 않는다. 우리 주님이 나사렛에서 쫓겨나신 뒤(마 4:13-16; 눅 4:16-31) 가버나움이 그분의 “자기 동네”가 되었다. 주님의 생애의 많은 행위와 사건의 현장이었다(마 8:5, 14-15; 9:2-6, 10-17; 15:1-20; 막 1:32-34 등). 주님이 그들 가운데서 자신의 사명이 참되다는 증거를 많이 보이셨는데도 주민이 회개하지 않고 믿지 않았으므로, 그들에게 무거운 심판의 선고가 내려졌다(마 11:23).\n\n이곳은 갈릴리 바다 서쪽 기슭에 있었다. 가버나움이 그 안은 아니더라도 가까이에 있었던 “게네사렛 땅”은 팔레스타인에서 가장 번영하고 붐비는 지역 가운데 하나였다. 이 성읍은 다메섹에서 악고와 두로로 가는 큰길 위에 있었다. 요단 강이 호수로 흘러드는 곳에서 남서쪽으로 약 2마일의 텔 훔으로 비정되었다. 여기에는 성벽과 기초의 넓은 폐허가 있고, 아름다운 회당이었을 것이 분명한 유적도 남아 있는데, 이 회당이 백부장이 지은 것(눅 7:5), 곧 우리 주님이 자주 가르치신 곳(요 6:59; 막 1:21; 눅 4:33)일 것이라고 추측한다. 다른 이들은 이 성읍의 폐허가 호숫가 남쪽으로 약 3마일 떨어진 칸 미니예에 있다고 추측했다. “텔 훔이 가버나움이라면, 말한 유적은 의심할 여지 없이 로마 백부장이 지은 회당의 폐허이며 지상에서 가장 거룩한 곳 가운데 하나이다. 우리 주님이 요 6장의 유명한 말씀을 하신 곳이 바로 이 건물이었다. 큰 돌덩이를 뒤집었을 때 그 앞면에 새겨진 만나 항아리를 발견하고 ‘내가 곧 생명의 떡이다. 너희 조상들은 광야에서 만나를 먹었어도 죽었다’는 말씀을 떠올리면서 어딘지 모를 야릇한 느낌이 없지 않았다.” (『예루살렘의 회복』.)","source_sha256":"08839ee4eec48cc2c0f922998d38d6a3641aa2d9efff55ba62cb1e72f4ba332f","citation_candidates":[{"source":"Matt. 4:13-16","passage":"mat-4","verse":13,"ref":"mat-4:13","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 4:16-31","passage":"luk-4","verse":16,"ref":"luk-4:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 8:5","passage":"mat-8","verse":5,"ref":"mat-8:5","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Mark 1:32-34","passage":"mrk-1","verse":32,"ref":"mrk-1:32","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 11:23","passage":"mat-11","verse":23,"ref":"mat-11:23","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 7:5","passage":"luk-7","verse":5,"ref":"luk-7:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 6:59","passage":"jhn-6","verse":59,"ref":"jhn-6:59","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Mark 1:21","passage":"mrk-1","verse":21,"ref":"mrk-1:21","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 4:33","passage":"luk-4","verse":33,"ref":"luk-4:33","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“나훔의 동네”라는 뜻의 갈릴리 성읍으로, 예수께서 나사렛에서 쫓겨나신 뒤 “자기 동네”로 삼으신 곳입니다."},{"candidate_id":"ATLBC-CAND-0021","name_en":"Carchemish","name_ko":"갈그미스","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CARCHEMISH","ko":"갈그미스. Carchemish\n“그모스의 요새”라는 뜻이다. 유프라테스 강 서안의 성읍으로(렘 46:2; 대하 35:20), 한때 생각했던 것처럼 크바르 강과 유프라테스 강이 합류하는 곳의 키르케시움이 아니라 강을 훨씬 더 거슬러 올라간 곳이며 유프라테스를 건너는 통상의 나루를 지배하는 성읍이다. 아마 히에라폴리스와 같은 곳일 것이다. 북부 헷 왕국의 수도였다. 나보폴라살의 아들 느부갓네살이 이끄는 바벨로니아 군대가 여기서 이집트 왕 바로 느고의 군대를 만나 이겼다(주전 607년). 주전 1600년의 기념비부터 주전 717년까지의 기념비에 언급되어 있다.","source_sha256":"d8898f60dbb6c8da37ac61b9e6b045c80f585ed93cf8fb0074e52fe67b958b73","citation_candidates":[{"source":"Jer. 46:2","passage":"jer-46","verse":2,"ref":"jer-46:2","status":"KRV_VERIFIED","exact_korean_token":"갈그미스"},{"source":"2 Chr. 35:20","passage":"2ch-35","verse":20,"ref":"2ch-35:20","status":"KRV_VERIFIED","exact_korean_token":"갈그미스"}],"status":"READER_REFERENCE_ONLY","intro_ko":"유프라테스 강 서안에 있던 북부 헷 왕국의 수도로, 바벨로니아 군대와의 큰 싸움이 벌어진 곳입니다."},{"candidate_id":"ATLBC-CAND-0022","name_en":"Chorazin","name_ko":"고라신","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CHORAZIN","ko":"고라신. Chorazin\n벳새다와 가버나움과 함께 우리 주님의 “능력”이 행해진 성읍의 하나로 언급되며, 두드러진 특권을 소홀히 했기 때문에 화가 선고되었다(마 11:21; 눅 10:13). 일반의 동의로 지금의 케라제로 비정되었는데, 가버나움에서 와디 케라제를 따라 올라가 약 2.5마일, 곧 텔 훔이다.","source_sha256":"cbfd380f4059435e6233f862258d850780b3b60789cb4d0e9a2cdcbd0ba23052","citation_candidates":[{"source":"Matt. 11:21","passage":"mat-11","verse":21,"ref":"mat-11:21","status":"KRV_VERIFIED","exact_korean_token":"고라신"},{"source":"Luke 10:13","passage":"luk-10","verse":13,"ref":"luk-10:13","status":"KRV_VERIFIED","exact_korean_token":"고라신"}],"status":"READER_REFERENCE_ONLY","intro_ko":"벳새다, 가버나움과 함께 주님의 “능력”이 행해졌으나 특권을 소홀히 하여 화를 선고받은 성읍입니다."},{"candidate_id":"ATLBC-CAND-0023","name_en":"Cilicia","name_ko":"길리기아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CILICIA","ko":"길리기아. Cilicia\n소아시아 남동쪽의 해안 속주이다. 바울의 출생지 다소가 이곳의 주요 성읍 가운데 하나였고 유명한 철학 학파가 있던 곳이었다. 마게도냐 제국에 편입된 뒤 쾌적한 기후가 많은 그리스인 주민을 끌어들였다. 주전 67년에 로마 속주가 되었다. 길리기아의 유다 사람은 예루살렘에 회당이 있었다(행 6:9). 바울은 회심 직후 이곳을 방문했고(갈 1:21; 행 9:30), 제2차 전도 여행 때에도 “수리아와 길리기아를 두루 다니며 교회들을 굳게 했다”(15:41). 길리기아는 킬리키움이라 불리는 염소 털 천으로 유명했다. 바울은 젊은 시절 이 천으로 천막을 만드는 일을 배웠다.","source_sha256":"bde8ff30e4704186744747c9c983fc1c3e0644b440d64117c4fa85ac192283f0","citation_candidates":[{"source":"Acts 6:9","passage":"act-6","verse":9,"ref":"act-6:9","status":"KRV_VERIFIED","exact_korean_token":"길리기아"},{"source":"Gal. 1:21","passage":"gal-1","verse":21,"ref":"gal-1:21","status":"KRV_VERIFIED","exact_korean_token":"길리기아"},{"source":"Acts 9:30","passage":"act-9","verse":30,"ref":"act-9:30","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아 남동쪽의 해안 지방으로, 바울의 고향 다소가 주요 성읍이었습니다."},{"candidate_id":"ATLBC-CAND-0024","name_en":"Corinth","name_ko":"고린도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CORINTH","ko":"고린도. Corinth\n펠로폰네소스를 그리스 본토와 잇는 지협에 있던 그리스 도시이다. 아덴에서 서쪽으로 약 48마일 떨어져 있다. 옛 도시는 로마인에게 파괴되었고(주전 146년), 신약에 나오는 도시는 약 백 년 뒤에 재건되어 로마에서 온 해방 노예 식민단이 사는 아주 새로운 도시였다. 로마 시대에 남부 그리스, 곧 아가야의 통치 중심지가 되었다(행 18:12-16). 부유함과, 사치스럽고 부도덕하고 악한 주민의 습관으로 이름이 났다. 로마인과 그리스인과 유다 사람이 많이 섞여 살았다. 바울이 처음 이 도시를 방문했을 때(주후 51년 또는 52년) 세네카의 형제 갈리오가 총독이었다. 여기서 바울은 일 년 반을 살았다(18:1-18). 여기서 처음 아굴라와 브리스길라를 알게 되었고, 그가 떠난 직후 아볼로가 에베소에서 이곳으로 왔다. 얼마 뒤 바울은 두 번째로 이곳을 방문하여 석 달을 머물렀다(20:3). 이 두 번째 방문 중에 로마서가 쓰였다(아마 주후 55년). 고린도에는 유다인 개종자가 많았으나 교회에서는 이방인의 요소가 우세했다.\n\n일부는 고후 12:14; 13:1에서 바울이 세 번째로 고린도를 방문했다고(곧 흔히 첫째와 둘째 방문이라 부르는 사이에 기록되지 않은 때에 이 도시를 방문했다고) 주장했다. 그러나 인용된 구절들은 바울이 고린도를 방문하려는 의도를 나타낼 뿐이며(비교 고전 16:5, 헬라어 현재 시제는 의도를 나타냄), 그 의도는 어떤 이유로 좌절되었다. 사도가 이런 방문을 하고도 더 분명한 언급이 없다고는 생각하기 어렵다.","source_sha256":"80eea674c30428d08beb1c83c1f628f480989de6c2901d53a6b2f48c9876375e","citation_candidates":[{"source":"Acts 18:12-16","passage":"act-18","verse":12,"ref":"act-18:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Cor. 12:14","passage":"2co-12","verse":14,"ref":"2co-12:14","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Cor. 16:5","passage":"1co-16","verse":5,"ref":"1co-16:5","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"펠로폰네소스를 그리스 본토와 잇는 지협의 그리스 도시로, 로마 때 남부 그리스의 통치 중심이 되었습니다."},{"candidate_id":"ATLBC-CAND-0025","name_en":"Crete","name_ko":"그레데","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CRETE","ko":"그레데. Crete\n지금은 칸디아라 불리며, 지중해에서 가장 큰 섬 가운데 하나로 길이 약 140마일, 너비 35마일이다. 한때 “백 개의 성읍”을 가진 매우 번영하고 인구가 많은 섬이었다. 주민의 성격은 바울이 디도에게 보낸 편지에서 “그들 자신의 한 선지자”(에피메니데스)의 말을 인용한 데 묘사되어 있다. “그레데 사람은 항상 거짓말쟁이요 악한 짐승이요 게으른 배이다”(딛 1:12). 그레데에서 온 유다 사람이 오순절 날 예루살렘에 있었다(행 2:11). 바울은 로마로 가는 항해 중에 이 섬을 방문했다(행 27장). 후에 여기서 바울은 디도를 남겨 “장로들을 세우게” 했다(1:5). 일부는 이 섬이 갑돌 사람(참조) 곧 블레셋 사람의 본래 고향이었다고 추측했다.","source_sha256":"a43e3f9e5988f3ee7f6daef83323d5454e69f1e28f19b34c3c99650ea8ab6eaa","citation_candidates":[{"source":"Titus 1:12","passage":"tit-1","verse":12,"ref":"tit-1:12","status":"KRV_VERIFIED","exact_korean_token":"그레데"},{"source":"Acts 2:11","passage":"act-2","verse":11,"ref":"act-2:11","status":"KRV_VERIFIED","exact_korean_token":"그레데"}],"status":"READER_REFERENCE_ONLY","intro_ko":"지중해에서 가장 큰 섬 가운데 하나로, 바울이 디도서에서 그곳 사람의 성격을 인용한 곳입니다."},{"candidate_id":"ATLBC-CAND-0026","name_en":"Cyprus","name_ko":"구브로","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CYPRUS","ko":"구브로. Cyprus\n지중해에서 가장 큰 섬 가운데 하나로 길이 약 148마일, 너비 40마일이다. 수리아 해안에서 약 60마일 떨어져 있다. 구약의 “깃딤”이다(민 24:24). 그리스 식민지 개척자들이 이 섬에 자라던 키프로스, 곧 헤나(고벨화 항목 참조)에서 따와 키프로스라는 이름을 붙였다. 본래 페니키아 사람이 살았다. 주전 477년에 그리스의 지배 아래 들어갔고 주전 58년에 로마 속주가 되었다. 고대에는 큰 상업 활동의 중심이었다. 곡식과 포도주와 기름이 가장 훌륭하게 생산되었다. 목재와 광물 자원도 풍부했다.\n\n신약에서는 바나바의 고향으로 처음 언급된다(행 4:36). 바울의 첫 선교 사역의 현장이었는데(13:4-13), 그와 바나바와 요한 마가가 안디옥 교회의 파송을 받았다. 후에는 바나바와 마가만 이곳을 찾았다(15:39). 아마 이 섬 출신으로 오순절에 개종한 사람 가운데 하나였을 “오랜 제자” 므나손이 언급된다(21:16). 바울의 항해와 관련해서도 언급된다(행 21:3; 27:4). 삼백 년 동안 터키 사람의 지배를 받은 뒤 1878년에 영국 정부에 양도되었다.","source_sha256":"26b2fbeb83a4b66e5d283c8f677cf1a87315264be85400bf8edda67c3b086807","citation_candidates":[{"source":"Num. 24:24","passage":"num-24","verse":24,"ref":"num-24:24","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 4:36","passage":"act-4","verse":36,"ref":"act-4:36","status":"KRV_VERIFIED","exact_korean_token":"구브로"},{"source":"Acts 21:3","passage":"act-21","verse":3,"ref":"act-21:3","status":"KRV_VERIFIED","exact_korean_token":"구브로"}],"status":"READER_REFERENCE_ONLY","intro_ko":"지중해의 큰 섬으로, 구약의 “깃딤”이며 본래 페니키아 사람이 살았습니다."},{"candidate_id":"ATLBC-CAND-0027","name_en":"Cyrene","name_ko":"구레네","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CYRENE","ko":"구레네. Cyrene\n북아프리카 상(上)리비아의 성읍(지금의 트리폴리)으로, 그리스 식민단이 세웠다(주전 630년). 후에는 많은 유다 사람이 살았는데, 라구스의 아들 프톨레마이오스가 그들이 이 성읍의 안전에 기여할 것이라고 생각하여 이곳으로 데려왔다. 그들은 수와 영향력이 늘어, 초기 기독교 역사와 관련하여 그들이 자주 언급되는 것도 이해할 만하다. 우리 주님의 십자가를 진 시몬이 이곳 사람이었다(마 27:32; 막 15:21). 구레네에서 온 유다 사람이 오순절에 예루살렘에 있었고(행 2:10), 구레네 유다 사람은 예루살렘에 회당이 있었다(6:9). 구레네 출신 개종자들은 안디옥에 첫 이방인 교회가 세워지는 데 이바지했다(11:20). “안디옥 교회에서 주를 섬기던 선지자와 교사들” 가운데 구레네 사람 루기오가 있었다(13:1).","source_sha256":"04df3a6e20e93ddbdffa45609af0b4b323d3bd10de51b8b5dfcd93d5390b1618","citation_candidates":[{"source":"Matt. 27:32","passage":"mat-27","verse":32,"ref":"mat-27:32","status":"KRV_VERIFIED","exact_korean_token":"구레네"},{"source":"Mark 15:21","passage":"mrk-15","verse":21,"ref":"mrk-15:21","status":"KRV_VERIFIED","exact_korean_token":"구레네"},{"source":"Acts 2:10","passage":"act-2","verse":10,"ref":"act-2:10","status":"KRV_VERIFIED","exact_korean_token":"구레네"}],"status":"READER_REFERENCE_ONLY","intro_ko":"북아프리카 리비아의 그리스 식민 도시로, 많은 유다 사람이 살았고 초대 교회 역사에 자주 등장합니다."},{"candidate_id":"ATLBC-CAND-0028","name_en":"Decapolis","name_ko":"데가볼리","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DECAPOLIS","ko":"데가볼리. Decapolis\n“열 성읍”이라는 뜻으로 데카(열)와 폴리스(성읍)에서 왔다. 갈릴리 바다 동쪽과 남동쪽에 있던 “열 성읍”을 포함하는 지역으로, 주로 그리스 사람이 살았다. 바산과 길르앗의 일부를 포함했고 신약에 세 번 언급된다(마 4:25; 막 5:20; 7:31). 이 성읍들은 스키토폴리스(곧 “스키타이 사람의 성읍”, 옛 벧산이며 열 성읍 가운데 요단 서쪽에 있는 유일한 곳), 힙포스, 가다라, 펠라(예루살렘 멸망 직전 그리스도인이 피신한 곳), 빌라델비아(옛 랍바 암몬), 게라사, 디온, 카나타, 라파나, 다메섹이다. 로마가 시리아를 정복했을 때(주전 65년) 이 “열 성읍”을 재건하고 일정한 특권을 주었으며, 이에 속한 지방을 “데가볼리”라 불렀다.","source_sha256":"1e2fa5c9e8728aa2c382b4f4438a97ee880ca7e31f1cce610b147e5850cdf2ef","citation_candidates":[{"source":"Matt. 4:25","passage":"mat-4","verse":25,"ref":"mat-4:25","status":"KRV_VERIFIED","exact_korean_token":"데가볼리"},{"source":"Mark 5:20","passage":"mrk-5","verse":20,"ref":"mrk-5:20","status":"KRV_VERIFIED","exact_korean_token":"데가볼리"}],"status":"READER_REFERENCE_ONLY","intro_ko":"갈릴리 바다 동쪽과 남동쪽에 있던, 주로 헬라 사람이 사는 “열 성읍”의 지역입니다."},{"candidate_id":"ATLBC-CAND-0029","name_en":"Derbe","name_ko":"더베","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DERBE","ko":"더베. Derbe\n루가오니아 고원 평야 동부의 작은 성읍으로 루스드라에서 약 20마일 떨어져 있다. 바울은 제2차 전도 여행 때 길리기아에서 이고니온으로 가는 길에 더베를 지났고(행 16:1), 아마 제3차 여행 때에도 지났을 것이다(18:23; 19:1). 첫 여행(14:20-21)에서는 반대쪽, 곧 이고니온에서 더베로 왔다. 바울의 동행자 가이오의 고향이다(20:4). 바울은 여기서는 박해를 받지 않았다(딤후 3:11).","source_sha256":"0cb35bae8427c459822fb733f6569f9e21f4a05dfb63a088bfa80c04950a90a5","citation_candidates":[{"source":"Acts 16:1","passage":"act-16","verse":1,"ref":"act-16:1","status":"KRV_VERIFIED","exact_korean_token":"더베"},{"source":"2 Tim. 3:11","passage":"2ti-3","verse":11,"ref":"2ti-3:11","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"루가오니아 고원 동부의 작은 성읍으로, 바울이 전도 여행 때 지난 곳이며 동료 가이오의 고향입니다."},{"candidate_id":"ATLBC-CAND-0030","name_en":"Dothan","name_ko":"도단","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DOTHAN","ko":"도단. Dothan\n“두 우물”이라는 뜻이다. 요셉이 형들이 양 떼를 지키는 것을 발견한 유명한 목초지이다. 여기서 유다의 제안으로 형들이 그를 이스마엘 상인들에게 팔았다(창 37:17). 주전 1600년의 기념비에 언급되어 있다.\n\n엘리사의 거처였고(왕하 6:13), 성이 서 있던 산을 불말과 불병거가 에워싼 놀라운 환상의 현장이었다. 이스르엘 평야 남쪽, 길보아 구릉 사이에 있으며 사마리아에서 북쪽으로 약 12마일 떨어진 지금의 텔 도단으로 비정된다. “두 우물”은 지금도 있으며 그중 하나는 “요셉의 구덩이”(줍 유수프)라는 이름을 지니고 있다.","source_sha256":"728c205ee7442752f653701a0909f4ba4f5cbf200747317323528753d2e11f61","citation_candidates":[{"source":"Gen. 37:17","passage":"gen-37","verse":17,"ref":"gen-37:17","status":"KRV_VERIFIED","exact_korean_token":"도단"},{"source":"2 Kings 6:13","passage":"2ki-6","verse":13,"ref":"2ki-6:13","status":"KRV_VERIFIED","exact_korean_token":"도단"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“두 우물”이라는 뜻의 유명한 목초지로, 요셉이 형들에게 팔린 곳이자 엘리사의 거처였습니다."},{"candidate_id":"ATLBC-CAND-0031","name_en":"En-gedi","name_ko":"엔게디","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ENGEDI","ko":"엔게디. Engedi\n“새끼 염소의 샘”이라는 뜻이다. 유다 광야에 있는 곳(수 15:62)으로, 사해 서안(겔 47:10)에 있고 사해 양쪽 끝에서 거의 같은 거리에 있다. 다윗은 사울이 두려워 이 성읍 근처의 광야로 도망했다(수 15:62; 삼상 23:29). 처음에는 하사손다말이라 불렸으며 아모리 사람의 성읍이었다(창 14:7).\n\n엔게디의 포도원은 솔로몬 시대에 유명했다(아 1:4). 지금의 아인 지디이다. 이름의 근원인 “샘”은 해발 약 600피트 산비탈에서 솟으며, 빠르게 흘러내리며 주변을 온통 무성하게 한다. 그 기슭을 따라 오셰르가 풍성하게 자란다. 포터는 이 관목을 이렇게 묘사한다. “줄기는 굵어서 직경이 거의 1피트에 이르기도 하고, 높이는 15피트 이상 자란다. 껍질은 회색빛이며 긴 타원형 잎은 꺾으면 젖빛 액체가 나온다. 열매는 사과와 비슷하고 두세 개씩 송이로 달린다. 익으면 짙은 노란색이지만 누르면 먼지버섯처럼 터진다. 대부분이 공기로 차 있다. ... 이것이 이른바 ‘소돔의 사과’이다.” (사마리아를 지나며 등.) (사과 항목 참조.)","source_sha256":"a976fdc38e335e99e6e9deb37ae9b7aaeac4d974b282d7cd610d24aa300eed5c","citation_candidates":[{"source":"Josh. 15:62","passage":"jos-15","verse":62,"ref":"jos-15:62","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Ezek. 47:10","passage":"ezk-47","verse":10,"ref":"ezk-47:10","status":"KRV_VERIFIED","exact_korean_token":"엔게디"},{"source":"1 Sam. 23:29","passage":"1sa-23","verse":29,"ref":"1sa-23:29","status":"KRV_VERIFIED","exact_korean_token":"엔게디"},{"source":"Gen. 14:7","passage":"gen-14","verse":7,"ref":"gen-14:7","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“새끼 염소의 샘”이라는 뜻으로, 사해 서안 유다 광야의 성읍이며 다윗이 사울을 피해 간 곳입니다."},{"candidate_id":"ATLBC-CAND-0032","name_en":"Emmaus","name_ko":"엠마오","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EMMAUS","ko":"엠마오. Emmaus\n“온천”이라는 뜻이다. 예루살렘에서 “육십 스타디온” 떨어진 마을로, 우리 주님이 부활하신 날 두 제자와 만나신 곳이다(눅 24:13). 예루살렘 북서쪽으로 7마일 남짓 떨어진 지금의 엘쿠베이베로 비정되었다. 이 이름 엘쿠베이베, 곧 “작은 둥근 지붕”은 지금도 그곳에서 볼 수 있는 십자군 교회의 유적에서 유래했다. 다른 이들은 예루살렘 남서쪽 약 8마일의 지금의 쿠르벳 카마사, 곧 “카마사의 폐허”로 비정하는데, 그곳에도 십자군 교회의 폐허가 있다. 그러나 그 터에 대해서는 논란이 많다.","source_sha256":"c4ce4bb3916f23f1de624d1ef2c61721892e5c90c64c54a34f097ba1b9bd94af","citation_candidates":[{"source":"Luke 24:13","passage":"luk-24","verse":13,"ref":"luk-24:13","status":"KRV_VERIFIED","exact_korean_token":"엠마오"}],"status":"READER_REFERENCE_ONLY","intro_ko":"부활하신 날 우리 주님이 두 제자와 만나신, 예루살렘에서 육십 스타디온 떨어진 마을입니다."},{"candidate_id":"ATLBC-CAND-0033","name_en":"Endor","name_ko":"엔돌","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ENDOR","ko":"엔돌. Endor\n“도르의 샘”, 곧 “세대의 샘”이라는 뜻이다. 잇사갈 영토 안의 곳으로(수 17:11), 드보라와 바락이 시스라와 야빈에게 거둔 큰 승리의 현장 가까이에 있다(비교 시 83:9-10). 사울은 블레셋과의 마지막 교전을 앞두고 점치는 여인으로 소문난 사람에게 물으려고 엔돌로 갔다(삼상 28:7). 작은 헤르몬 북쪽 비탈, 이스르엘에서 약 7마일 떨어진, “스무 채쯤의 집, 아니 오두막으로 이루어진 더러운 작은 마을로 대부분 허물어져 가는” 지금의 엔두르 마을로 비정되었다.","source_sha256":"99f0bb5f646dbc8ba4e0d58b04cfd2c717a31cecadc36c17accfbad2018fe614","citation_candidates":[{"source":"Josh. 17:11","passage":"jos-17","verse":11,"ref":"jos-17:11","status":"KRV_VERIFIED","exact_korean_token":"엔돌"},{"source":"Ps. 83:9","passage":"psa-83","verse":9,"ref":"psa-83:9","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 28:7","passage":"1sa-28","verse":7,"ref":"1sa-28:7","status":"KRV_VERIFIED","exact_korean_token":"엔돌"}],"status":"READER_REFERENCE_ONLY","intro_ko":"잇사갈 영토의 샘 마을로, 사울이 마지막 전투를 앞두고 점치는 여인을 찾아간 곳입니다."},{"candidate_id":"ATLBC-CAND-0035","name_en":"Ezion-geber","name_ko":"에시온게벨","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EZION-GEBER","ko":"에시온게벨. Ezion-geber\n“거인의 등뼈”라는 뜻이다(바다로 뻗은 산 머리에서 이렇게 불렸다). 홍해의 엘라닛 갈래, 곧 아카바 만 북동쪽 끝 엘랏 또는 엘롯 가까이에 있던 옛 성읍이자 항구이다(민 33:35; 신 2:8). 여기서 솔로몬은 두로에서 다시스와 서방으로 교역하던 것과 같은 “다시스 배”를 지어 오빌과 교역했고(왕상 9:26; 대하 8:17), 여호사밧의 함대도 여기서 파선했다(왕상 22:48; 대하 20:36). 많은 유다 사람이 정착하여 인구가 많은 성읍이 되었다(왕하 16:6, “엘랏”). 옛날에는 만의 북쪽 끝이 지금보다 더 내륙 깊이, 아라바의 마른 하상을 따라 10마일 위쪽의 아인 엘구디얀까지 들어와 있었으며 에시온게벨이 그곳에 있었을 것이라고 추측한다.","source_sha256":"1a3816a7c099917bbd849b10d4627f8e0879bf6f5e0988554099a53101f05e9e","citation_candidates":[{"source":"Num. 33:35","passage":"num-33","verse":35,"ref":"num-33:35","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"Deut. 2:8","passage":"deu-2","verse":8,"ref":"deu-2:8","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 9:26","passage":"1ki-9","verse":26,"ref":"1ki-9:26","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Chr. 8:17","passage":"2ch-8","verse":17,"ref":"2ch-8:17","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"1 Kings 22:48","passage":"1ki-22","verse":48,"ref":"1ki-22:48","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Chr. 20:36","passage":"2ch-20","verse":36,"ref":"2ch-20:36","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Kings 16:6","passage":"2ki-16","verse":6,"ref":"2ki-16:6","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"홍해 아카바 만 북동쪽 끝의 옛 항구 도시로, 솔로몬이 다시스 배를 건조한 곳입니다."},{"candidate_id":"ATLBC-CAND-0037","name_en":"Gadara","name_ko":"가다라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GADARA","ko":"가다라. Gadara\n로마 속주 베레아의 수도이다. 갈릴리 바다에서 남동쪽으로 약 6마일, 산꼭대기에 서 있었다. 마가(5:1)와 누가(8:26-39)는 귀신 들린 사람(마태[8:28-34]는 두 사람이라 함)을 고친 기적이 “가다라 사람의 지방에서” 일어났다고 하여 현장을 대략으로 서술한다. 호수와 이 성읍 사이에 히에로막스(야르묵)의 깊고 거의 건널 수 없는 협곡이 있으므로, 그 기적은 가다라 자체에서 일어났을 수는 없다. 지금의 마을 움 카이스로 비정되며, 마을은 매우 넓은 폐허에 둘러싸여 있고 그 모두가 옛 가다라의 화려함을 증언한다.\n\n“가다라의 가장 흥미로운 유적은 무덤들로, 성 둘레의 상당한 거리에 걸쳐 절벽에 점점이 흩어져 있고 주로 북동쪽 비탈에 있다. 그러나 아름답게 조각된 석관도 주변 높은 곳에 많이 흩어져 있다. 석회암 바위를 파서 만든 것으로 여러 크기의 방으로 이루어져 있으며, 일부는 한 변이 20피트가 넘고 옆면에 시신을 두는 움푹한 곳이 있다. ... 움 카이스의 현재 주민은 모두 동굴 거주자로, 옛 불쌍한 광인들처럼 ‘무덤 사이에 살며’ 때로는 방어할 수단이 없는 나그네에게 거의 그들만큼 위험하다.”","source_sha256":"e8f7dc11f41460ed88880ff142c39757f09973b79ea08e606e7fad7ff1d4b618","citation_candidates":[],"status":"READER_REFERENCE_ONLY","intro_ko":"갈릴리 바다 남동쪽 약 6마일 산 위에 있던 로마 속주 베레아의 수도로, 그 일대에서 귀신 들린 사람의 치유가 있었습니다."},{"candidate_id":"ATLBC-CAND-0038","name_en":"Gennesaret","name_ko":"게네사렛","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GENNESARET","ko":"게네사렛. Gennesaret\n“풍요의 동산”이라는 뜻이다. (1) 납달리의 성읍으로 긴네렛(수 19:35)이라 불렸고 때로는 복수형 긴네롯(11:2)으로 나온다. 후대에는 이름이 차츰 겐네살과 게네사렛(눅 5:1)으로 바뀌었다. 이 성읍은 자기 이름을 준 호수의 서안에 서 있었다. 흔적은 남아 있지 않다. 게네사렛 평야는 그 비옥함과 아름다움 때문에 “갈릴리의 낙원”이라 불렸다. 지금은 엘구웨이르라 불린다.\n\n(2) 게네사렛 호수. 긴네렛(참조)의 헬라어화된 형태이다. (갈릴리 바다 항목 참조.)","source_sha256":"1614ef87916c8015959543dbcdbf7040f4e108c69a4212e7bce7152509aac28a","citation_candidates":[{"source":"Josh. 19:35","passage":"jos-19","verse":35,"ref":"jos-19:35","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Luke 5:1","passage":"luk-5","verse":1,"ref":"luk-5:1","status":"KRV_VERIFIED","exact_korean_token":"게네사렛"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“풍요의 동산”이라는 뜻으로, 갈릴리 바다 서안의 성읍과 그 일대의 비옥한 평야를 가리킵니다."},{"candidate_id":"ATLBC-CAND-0039","name_en":"Gerar","name_ko":"그랄","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GERAR","ko":"그랄. Gerar\n“지역”, “머무는 곳”이라는 뜻이다. 팔레스타인 남쪽 경계에 있던 아주 오래된 성읍이자 지방으로, 아비멜렉이라는 왕이 다스렸다(창 10:19; 20:1-2). 아브라함이 이곳에 머물렀고 아마 이삭이 이곳에서 태어났을 것이다. 두 족장 모두 여기서 아내를 부인하는 죄를 지었고, 두 사람 모두 브엘세바로 떠나기 전에 왕과 조약을 맺었다(21:23-34; 26장). 풍요로운 목축지였던 듯하다(대하 14:12-18). 이삭은 여기서 백배의 수확을 거두어 하나님께 복을 받았다(창 26:12). “그랄 골짜기”(창 26:17)는 아마 지금의 와디 엘제르드일 것이다.","source_sha256":"555537f86c3f7289ed936e4dbaee39237d0b42590b3a2908dcd380136bf2d81e","citation_candidates":[{"source":"Gen. 10:19","passage":"gen-10","verse":19,"ref":"gen-10:19","status":"KRV_VERIFIED","exact_korean_token":"그랄"},{"source":"2 Chr. 14:12-18","passage":"2ch-14","verse":12,"ref":"2ch-14:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 26:12","passage":"gen-26","verse":12,"ref":"gen-26:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 26:17","passage":"gen-26","verse":17,"ref":"gen-26:17","status":"KRV_VERIFIED","exact_korean_token":"그랄"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“지역”, “머무는 곳”이라는 뜻으로, 팔레스타인 남쪽 변경에 있던 아주 오래된 성읍이며 아비멜렉 왕이 다스렸습니다."},{"candidate_id":"ATLBC-CAND-0040","name_en":"Gezer","name_ko":"게셀","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GEZER","ko":"게셀. Gezer\n“낭떠러지”라는 뜻이다. 가나안 사람의 옛 왕성이다(수 10:33; 12:12). 교외와 함께 고핫 자손 레위 사람에게 배정되었다(21:21; 대상 6:67). 아랫벧호론과 바다 사이에 있었다(수 16:3; 왕상 9:17). 다윗이 바알브라심 전투 뒤 블레셋 사람을 추격한 마지막 지점이었다(삼하 5:25; 대상 14:16). 가나안 사람은 솔로몬 때까지 이곳을 소유했고, 그때 이집트 왕이 이곳을 빼앗아 솔로몬이 맞아들인 이집트 공주의 혼수의 일부로 솔로몬에게 주었다(왕상 9:15-17). 벧호론에서 남서쪽으로 약 10마일의 텔 엘제제르로 비정된다. 아마르나 점토판에 언급되어 있다.","source_sha256":"53d1c17460d95fb1ba0133e923b3e787140c4102b41968edc2387911846f710a","citation_candidates":[{"source":"Josh. 10:33","passage":"jos-10","verse":33,"ref":"jos-10:33","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Chr. 6:67","passage":"1ch-6","verse":67,"ref":"1ch-6:67","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"Josh. 16:3","passage":"jos-16","verse":3,"ref":"jos-16:3","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Kings 9:17","passage":"1ki-9","verse":17,"ref":"1ki-9:17","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"2 Sam. 5:25","passage":"2sa-5","verse":25,"ref":"2sa-5:25","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Chr. 14:16","passage":"1ch-14","verse":16,"ref":"1ch-14:16","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Kings 9:15-17","passage":"1ki-9","verse":15,"ref":"1ki-9:15","status":"KRV_VERIFIED","exact_korean_token":"게셀"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“낭떠러지”라는 뜻의 가나안 왕성으로, 고핫 자손 레위 사람에게 배정되었으며 아랫벧호론과 바다 사이에 있었습니다."},{"candidate_id":"ATLBC-CAND-0042","name_en":"Gilboa","name_ko":"길보아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GILBOA","ko":"길보아. Gilboa\n“끓는 샘”이라는 뜻이다. 지금의 제벨 푸쿠아라 불리는 산맥으로, 사울이 블레셋에게 참패한 현장으로 기억된다. 여기서 그의 세 아들도 죽었고 그 자신은 스스로 목숨을 끊었다(삼상 28:4; 31:1-8; 삼하 1:6-21; 21:12; 대상 10:1, 8). 에스드라엘론(이스르엘) 골짜기와 요단 골짜기 사이에서 골짜기의 동쪽을 경계 짓는, 낮고 메마른 산맥이었다. 이 패배의 소식이 다윗에게 전해졌을 때 그는 “활의 노래”(삼하 1:19-27)의 그 애절한 말을 쏟아냈다.","source_sha256":"221e743ff62aadaf4898e77158867072335d1f1b9aa2cdd17ab82ce79a33b4a7","citation_candidates":[{"source":"1 Sam. 28:4","passage":"1sa-28","verse":4,"ref":"1sa-28:4","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"2 Sam. 1:6-21","passage":"2sa-1","verse":6,"ref":"2sa-1:6","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"1 Chr. 10:1","passage":"1ch-10","verse":1,"ref":"1ch-10:1","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"2 Sam. 1:19-27","passage":"2sa-1","verse":19,"ref":"2sa-1:19","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“끓는 샘”이라는 뜻의 산맥으로, 사울이 블레셋에게 크게 패하고 죽은 곳입니다."},{"candidate_id":"ATLBC-CAND-0043","name_en":"Golgotha","name_ko":"골고다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GOLGOTHA","ko":"골고다. Golgotha\n예수께서 십자가에 못 박히신 곳의 일반적인 이름이다. 복음서 기자들은 이를 “해골의 곳”이라는 뜻으로 풀이한다(마 27:33; 막 15:22; 요 19:17). 이 이름은 아람어 굴갈타를 헬라 문자로 나타낸 것이며, 이는 히브리어 굴골레트(민 1:2; 대상 23:3, 24; 왕하 9:35), 곧 “해골”이다. 갈보리(참조)라는 말과 같다. 민둥한 해골처럼 둥글게 생긴 작은 언덕이었다. 복음서 기자들에게서 이곳이 성문 밖의 잘 알려진 장소였고(비교 히 13:12) 성에 가까웠으며(눅 23:26) “동산”이 있었고(요 19:41) 시골로 나가는 큰길 위에 있었음이 분명하다. 그러므로 이곳이 지금의 “성묘 교회” 안에 포함된다는 생각은 지지될 수 없다. 성 북쪽의 예레미야 동굴 위의 작은 언덕이 아마 갈보리의 진짜 터일 것이다. 이 언덕 남쪽 절벽 바위의 해골 같은 모양은 매우 눈에 띈다.","source_sha256":"8621fbdb41f84a821e2b5d6a0c43355526044bd29ee22c3e52ba578a5f7b7a58","citation_candidates":[{"source":"Matt. 27:33","passage":"mat-27","verse":33,"ref":"mat-27:33","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"Mark 15:22","passage":"mrk-15","verse":22,"ref":"mrk-15:22","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"John 19:17","passage":"jhn-19","verse":17,"ref":"jhn-19:17","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"Num. 1:2","passage":"num-1","verse":2,"ref":"num-1:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 23:3","passage":"1ch-23","verse":3,"ref":"1ch-23:3","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 9:35","passage":"2ki-9","verse":35,"ref":"2ki-9:35","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Heb. 13:12","passage":"heb-13","verse":12,"ref":"heb-13:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Luke 23:26","passage":"luk-23","verse":26,"ref":"luk-23:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 19:41","passage":"jhn-19","verse":41,"ref":"jhn-19:41","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“해골의 곳”이라는 뜻으로, 예수께서 십자가에 못 박히신 곳의 일반적인 이름입니다."},{"candidate_id":"ATLBC-CAND-0044","name_en":"Goshen","name_ko":"고센","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GOSHEN","ko":"고센. Goshen\n(1) 야곱과 그의 가족이 정착하여 출애굽 때까지 머문 이집트의 지방이다(창 45:10; 46:28, 29, 31 등). “고센 땅”(47:27)이라고도 하고 단순히 “고센”(46:28)이라고도 하며, 비돔과 라암셋 성읍이 그 경계 안에 있었으므로 “라암셋 땅”(47:11; 출 12:37)이라고도 한다. 소안 곧 타니스(시 78:12)도 이에 포함된다. 나일 강 동쪽에 있었고 왕의 거처에서 그리 멀지 않았던 듯하다. “땅의 가장 좋은 곳”(창 47:6, 11)이었으나 지금은 사막이다. 요셉이 아버지에게 보낸 전갈에서 처음 언급된다. 삼각주 동부와 팔레스타인 서쪽 경계 사이에 있는 지금의 와디 투밀라트로 비정되었다. 목축 지방으로 왕의 가축 일부가 그곳에서 길러졌다(창 47:6). 주민은 이스라엘 사람만은 아니었다(출 3:22; 11:2; 12:35-36).\n\n(2) 팔레스타인의 지방이다(수 10:41; 11:16). 유다 해안 평야의 일부로 가사와 기브온 사이에 있었다.\n\n(3) 유다 산지의 성읍이다(수 15:51).","source_sha256":"87b5cdc76fdc478fcf0be4eb6f97958730de8a65d1cd9e958369e4f7bd1f6d0c","citation_candidates":[{"source":"Gen. 45:10","passage":"gen-45","verse":10,"ref":"gen-45:10","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Ps. 78:12","passage":"psa-78","verse":12,"ref":"psa-78:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 47:6","passage":"gen-47","verse":6,"ref":"gen-47:6","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Josh. 10:41","passage":"jos-10","verse":41,"ref":"jos-10:41","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Josh. 15:51","passage":"jos-15","verse":51,"ref":"jos-15:51","status":"KRV_VERIFIED","exact_korean_token":"고센"}],"status":"READER_REFERENCE_ONLY","intro_ko":"야곱의 가족이 이집트에서 출애굽 때까지 정착해 산 지역으로, “라암셋 땅”이라고도 불립니다."},{"candidate_id":"ATLBC-CAND-0047","name_en":"Hazor","name_ko":"하솔","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-HAZOR","ko":"하솔. Hazor\n“울타리 친”, “요새화된”이라는 뜻이다. (1) 메롬 호수 북쪽 산지에 있던 가나안 사람의 요새이다(수 11:1-5). 야빈 왕이 동맹 부족들과 함께 여기서 여호수아와 큰 싸움을 벌였다. 여호수아가 뚜렷한 승리를 거두어 가나안 정복을 사실상 마무리했다(11:10-13). 그러나 이 성은 후에 가나안 사람이 다시 세웠고, 같은 세습 이름 야빈을 가진 왕이 다스렸다. 그의 군대는 시스라라는 유명한 지휘관의 지휘 아래 남쪽으로 휩쓸고 내려와 나라를 완전히 굴복시키려 했다. 이 강력한 군대는 여선지자 드보라의 조언에 따라 나아간 바락 휘하의 이스라엘 사람에게 맞았다. 그 결과는 구약에 기록된 이스라엘의 가장 놀라운 승리 가운데 하나였다(수 19:36; 삿 4:2; 삼상 12:9). 하솔 성은 점령되어 이스라엘 사람이 차지했다. 솔로몬은 수리아와 앗수르에서 왕국으로 들어오는 입구를 지키려고 이곳을 요새화했다. 앗수르 왕 디글랏빌레셀이 땅을 침공했을 때 이곳은 그가 처음 점령한 성읍 가운데 하나였고, 주민은 앗수르로 사로잡혀 갔다(왕하 15:29). 게데스 남동쪽 2.5마일의 쿠르벳 하라로 비정되었다.\n\n(2) 유다 남쪽의 성읍이다(수 15:23). 여기서 이름은 아마 뒤에 이어지는 낱말 이드난과 연결하여 “하솔과 이드난”이 아니라 하솔이드난으로 보아야 할 것이다.\n\n(3) 아라비아의 지방이다(렘 49:28-33). 일부는 이두래, 곧 이두매로 추정한다.\n\n(4) “그리욧과 헤스론”(수 15:25)은 (개정역처럼) “그리욧헤스론”이어야 한다. 두 이름이 하나로 연결되어 한 곳의 이름이 되며(예를 들어 기럇여아림처럼) “그것이 곧 하솔”이다(개정역). 이곳은 엘쿠리에타인으로 비정되었고, 가룟 유다의 고향일 것이라는 추측이 있었다. (그리욧 항목 참조.)","source_sha256":"69c243e5bc488d13367ee81507fdef5be3dbd3e7cb52127c15d61481e4e23953","citation_candidates":[{"source":"Josh. 11:1-5","passage":"jos-11","verse":1,"ref":"jos-11:1","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Josh. 19:36","passage":"jos-19","verse":36,"ref":"jos-19:36","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Judg. 4:2","passage":"jdg-4","verse":2,"ref":"jdg-4:2","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"1 Sam. 12:9","passage":"1sa-12","verse":9,"ref":"1sa-12:9","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"2 Kings 15:29","passage":"2ki-15","verse":29,"ref":"2ki-15:29","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Josh. 15:23","passage":"jos-15","verse":23,"ref":"jos-15:23","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Jer. 49:28-33","passage":"jer-49","verse":28,"ref":"jer-49:28","status":"KRV_VERIFIED","exact_korean_token":"하솔"}],"status":"READER_REFERENCE_ONLY","intro_ko":"메롬 호수 북쪽 산지에 있던 가나안의 요새로, 여호수아가 야빈 왕과 싸워 큰 승리를 거둔 곳입니다."},{"candidate_id":"ATLBC-CAND-0048","name_en":"Iconium","name_ko":"이고니온","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ICONIUM","ko":"이고니온. Iconium\n고대 루가오니아의 수도이다. 바울과 바나바가 첫 전도 여행 때 비시디아 안디옥에서 와서 처음 방문했다(행 13:50-51). 여기서 그들은 유다 사람에게 박해를 받고 성에서 쫓겨나 루스드라로 도망쳤다. 그 후 이고니온으로 돌아가 그곳에 세워진 교회를 격려했다(14:21-22). 바울은 제3차 전도 여행 때 실라와 함께 다시 이곳을 방문했을 것이다(18:23). 지금의 코니에로, 타우루스 산 기슭에 있으며 지중해에서 내륙으로 약 120마일 떨어져 있다.","source_sha256":"55df684c8892c11e6fad09a403334d77d5bb4d3743b835464134ebb53524d317","citation_candidates":[{"source":"Acts 13:50","passage":"act-13","verse":50,"ref":"act-13:50","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"고대 루가오니아의 수도로, 바울과 바나바가 비시디아 안디옥에서 와서 처음 전도한 곳입니다."},{"candidate_id":"ATLBC-CAND-0050","name_en":"Jabbok","name_ko":"얍복","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-JABBOK","ko":"얍복. Jabbok\n“쏟아짐” 또는 “씨름”이라는 뜻이다. 요단 동쪽의 시내 가운데 하나로, 갈릴리 바다와 사해의 거의 중간, 곧 갈릴리 바다에서 약 45마일 아래에서 요단 강으로 흘러든다. 길르앗 산지 동쪽에서 발원하여 깊고 거친 협곡을 따라 약 65마일을 흐른다. 암몬 사람의 영토와 바산 왕 옥의 영토 사이의 경계였고(수 12:1-5; 민 21:24), 르우벤 지파와 므낫세 반 지파 사이의 경계이기도 했다(21:24; 신 3:16). 서쪽으로 평야를 가로질러 흐르는 동안 한 번 이상 땅속으로 들어간다. “그 기슭을 따른 경치는 아마 팔레스타인에서 가장 그림 같을 것이며, 주변 산비탈에 점점이 흩어진 성읍과 마을과 요새의 폐허가 이 지방을 아름다운 만큼 흥미롭게 만든다.” 이 강은 지금 제르카, 곧 푸른 강이라 불린다.","source_sha256":"0194c018edd4cd05aef16e44284da400772680ff2f36b146b26f9bc7d62d2a13","citation_candidates":[{"source":"Josh. 12:1-5","passage":"jos-12","verse":1,"ref":"jos-12:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Num. 21:24","passage":"num-21","verse":24,"ref":"num-21:24","status":"KRV_VERIFIED","exact_korean_token":"얍복"},{"source":"Deut. 3:16","passage":"deu-3","verse":16,"ref":"deu-3:16","status":"KRV_VERIFIED","exact_korean_token":"얍복"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“쏟아짐” 또는 “씨름”이라는 뜻으로, 요단 동쪽에서 요단 강으로 흘러드는 강이며 암몬과 바산 왕 옥의 영토 경계였습니다."},{"candidate_id":"ATLBC-CAND-0051","name_en":"Joppa","name_ko":"욥바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-JOPPA","ko":"욥바. Joppa\n“아름다움”이라는 뜻이다. 단의 몫에 속한 성읍이며(수 19:46; 흠정역 “야보”), 가이사랴와 가사 사이의 모래 곶에 있고 예루살렘에서 북서쪽으로 30마일 떨어져 있다. 아시아에서 가장 오래된 성읍 가운데 하나이다. 유대의 주된 항구였고 지금도 그러하다. 페니키아 사람에게서 빼앗긴 적이 없었다. 주전 2세기에야 유다 사람의 성읍이 되었다. 요나가 “여호와의 낯을 피하여 도망하려고 배를 탄”(욘 1:3) 항구가 이곳이다. 히람의 사람들이 솔로몬을 위해 레바논에서 벤 목재도 뗏목으로 이곳에 운반되었고(대하 2:16), 둘째 성전을 건축할 재료도 이곳에 부려졌다(스 3:7). 욥바에서 베드로는 “바닷가”에 있는 무두장이 시몬의 집에서 “여러 날” 머물렀고, 거기서 “지붕 위에서” “관용의 환상”을 보았다(행 9:36-43). 지금의 이름은 자파이며, 터키 사람이 다스리는 도시들의 쇠락과 궁핍을 모두 드러낸다. “이만큼 자주 무너지고 약탈당하고 불타고 재건된 성읍은 거의 없다.” 현재 인구는 약 16,000명이라 한다. 1799년에 나폴레옹의 프랑스군에게 점령되었는데, 그는 이곳에서 포로 4,000명을 학살하라고 명령했다. 이곳은 나라에 있는 유일한 마찻길로 예루살렘과 이어져 있고 1892년에 완공된 철도로도 이어져 있다. 주전 1600~1300년의 기념비에 언급되어 있고 주전 702년에 산헤립에게 공격받았다.","source_sha256":"0dc92ea8ef3de75a0b1ef5845803e95d98dae6b0268f303b93aa1bdfac4d52cb","citation_candidates":[{"source":"Josh. 19:46","passage":"jos-19","verse":46,"ref":"jos-19:46","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Jonah 1:3","passage":"jon-1","verse":3,"ref":"jon-1:3","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"2 Chr. 2:16","passage":"2ch-2","verse":16,"ref":"2ch-2:16","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Ezra 3:7","passage":"ezr-3","verse":7,"ref":"ezr-3:7","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Acts 9:36-43","passage":"act-9","verse":36,"ref":"act-9:36","status":"KRV_VERIFIED","exact_korean_token":"욥바"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“아름다움”이라는 뜻으로, 단 지파의 몫이었던 유다의 주된 항구이며 요나가 배를 탄 곳입니다."},{"candidate_id":"ATLBC-CAND-0053","name_en":"Kishon","name_ko":"기손","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-KISHON","ko":"기손. Kishon\n“굽이침”이라는 뜻이다. 중부 팔레스타인의 겨울 급류로, 다볼과 길보아 기슭에서 발원하여 북쪽으로 에스드라엘론과 아코 평야를 지나 갈멜 기슭, 아코 만의 북동쪽 모퉁이에서 지중해로 흘러든다. 에스드라엘론 평야와 그것을 둘러싼 산지의 물이 바다로 나가는 배수로이다. 현대 이름은 나흐르 엘모카타, 곧 “학살의 강”이다(비교 왕상 18:40). 드보라의 승전가(삿 5:21)에서는 “옛 강”이라 하는데, (1) 오랜 세월 흘러왔기 때문이거나, (2) 탈굼에 따르면 “옛적에 이스라엘에게 표적과 기사가 보인 급류”였기 때문이거나, (3) 아마 그 지역에서 옛 가나안 사람 사이에 벌어진 용맹한 행적을 가리키는 것일 터인데, 인접한 에스드라엘론 평야가 팔레스타인의 큰 전쟁터였기 때문이다.\n\n이곳은 시스라가 패한 현장이며(삿 4:7, 13), 엘리야가 바알의 선지자들을 죽인 현장이다(왕상 18:40). “기손이 가장 불어났을 때는, 부분적으로 그 유사(流沙) 때문에 후퇴하는 군대에게는 바다만큼이나 건널 수 없었을 것이다.” (드보라 항목 참조.)","source_sha256":"850ca72d893ce7a05bc5adaebff10d0b368ec8ed44a357bc95d77b71e09bc6f2","citation_candidates":[{"source":"1 Kings 18:40","passage":"1ki-18","verse":40,"ref":"1ki-18:40","status":"KRV_VERIFIED","exact_korean_token":"기손"},{"source":"Judg. 5:21","passage":"jdg-5","verse":21,"ref":"jdg-5:21","status":"KRV_VERIFIED","exact_korean_token":"기손"},{"source":"Judg. 4:7","passage":"jdg-4","verse":7,"ref":"jdg-4:7","status":"KRV_VERIFIED","exact_korean_token":"기손"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“굽이침”이라는 뜻의 겨울 급류로, 다볼과 길보아 기슭에서 시작해 에스드라엘론 평야를 지나 지중해로 흘러듭니다."},{"candidate_id":"ATLBC-CAND-0054","name_en":"Laodicea","name_ko":"라오디게아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LAODICEA","ko":"라오디게아. Laodicea\n성경에 언급된 이 이름의 성읍은 브루기아와 루디아의 경계, 에베소에서 동쪽으로 약 40마일, 리코스 강변에 있었다(계 3:14). 본래 디오스폴리스, 그다음 로아스라 불렸고, 후에 시리아 왕 안티오코스 2세의 아내 라오디케가 재건하여 그의 이름을 따 라오디게아라 불렸다. 소아시아에서 가장 중요하고 번영한 성읍 가운데 하나였다. 아주 이른 시기에 기독교의 주요 중심지가 되었다(골 2:1; 4:15; 계 1:11 등). 지금은 버려진 곳으로 터키 사람이 에스키히사르, 곧 “옛 성”이라 부른다.","source_sha256":"1809acd2f63f72ecd3e76e538138118a2997b1c69b01c71735a99c168b3437f0","citation_candidates":[{"source":"Rev. 3:14","passage":"rev-3","verse":14,"ref":"rev-3:14","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"},{"source":"Col. 2:1","passage":"col-2","verse":1,"ref":"col-2:1","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"},{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"브루기아와 루디아 경계, 에베소 동쪽 약 40마일 리코스 강변에 있던 아시아의 번영한 성읍입니다."},{"candidate_id":"ATLBC-CAND-0055","name_en":"Lydda","name_ko":"룻다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LYDDA","ko":"룻다. Lydda\n에브라임 지파에 있던 성읍으로, 신약에서만 베드로가 중풍병자 애니아를 고친 기적의 현장으로 언급된다(행 9:32, 35, 38). 욥바에서 동쪽으로 약 9마일, 항구에서 예루살렘으로 가는 길 위에 있었다. 구약(대상 8:12)에서는 로드라 불린다. 로마인에게 불탔으나 후에 재건되어 디오스폴리스라는 이름으로 알려졌다. 현대 이름은 루드이다. 영국의 이른바 수호성인 성 조지가 이곳에서 태어났다고 한다.","source_sha256":"3f1d9e8d4d65b654f505bf172f9ad047dec2e7976edf210b6295e3bd1a1ff3c0","citation_candidates":[{"source":"Acts 9:32","passage":"act-9","verse":32,"ref":"act-9:32","status":"KRV_VERIFIED","exact_korean_token":"룻다"},{"source":"1 Chr. 8:12","passage":"1ch-8","verse":12,"ref":"1ch-8:12","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"욥바 동쪽 약 9마일에 있던 성읍으로, 베드로가 중풍병자 애니아를 고친 곳입니다."},{"candidate_id":"ATLBC-CAND-0056","name_en":"Lystra","name_ko":"루스드라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LYSTRA","ko":"루스드라. Lystra\n소아시아 루가오니아의 거친 지방, 투박한 주민 가운데 있던 성읍이다. 바울은 이고니온에서 박해로 쫓겨난 뒤 여기서 복음을 전했다(행 14:2-7). 여기서 그는 앉은뱅이를 고쳤고(8절), 이에 무지하고 미신적인 사람들이 깊은 인상을 받아 그를 “주된 연설자”라 하여 헤르메스로, 동행한 바나바는 아마 그의 위엄 있고 존엄한 모습 때문에 제우스로 여기고 그들에게 제사를 드리려 했는데(13절), 바울이 진지하게 그들에게 말하여 모든 복의 참된 근원으로 그들의 눈을 돌렸다. 그러나 곧 비시디아 안디옥과 이고니온에서 온 유다 사람들의 영향으로 그들은 바울을 돌로 쳐서 죽은 줄 알고 버려두었다(14:19). 바울은 회복되어 더베로 떠났으나 곧 루스드라를 거쳐 다시 돌아와 그곳 제자들에게 굳건히 서라고 격려했다. 그는 제3차 전도 여행 때 이 성을 다시 방문했을 가능성이 높다(행 18:23). 아마 이곳에서 태어났을 디모데(딤후 3:10-11)는 이때 바울이 루스드라에서 받은 박해와 용기를 목격한 사람들 가운데 하나였음이 틀림없다.","source_sha256":"e45312976022dcf40c4aaca95fc1b2bed3f520adce7238b7cac95a73d6bd27d2","citation_candidates":[{"source":"Acts 14:2-7","passage":"act-14","verse":2,"ref":"act-14:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 18:23","passage":"act-18","verse":23,"ref":"act-18:23","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Tim. 3:10","passage":"2ti-3","verse":10,"ref":"2ti-3:10","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아 루가오니아의 거친 지역에 있던 성읍으로, 바울이 앉은뱅이를 고쳐 사람들이 그를 신으로 여긴 곳입니다."},{"candidate_id":"ATLBC-CAND-0057","name_en":"Magdala","name_ko":"막달라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAGDALA","ko":"막달라. Magdala\n“망대”라는 뜻이다. 갈릴리의 성읍으로 마 15:39에만 나온다. 병행 구절 막 8:10에서는 이곳을 달마누다라 부른다. 막달라 마리아라 불리는 마리아의 출생지이다. 디베랴 호수 서안에 있었고, 지금은 아마 디베랴 북서쪽 약 3마일의 엘메즈델이라는 작고 외진 마을일 것이다. 탈무드에서는 이 성읍을 “염색의 성읍”이라 부르고, 그 한 구역을 “염색공의 망대”라 불렀다. 쪽(인디고) 식물이 이곳에서 많이 재배되었다.","source_sha256":"5093dddebfa7aa3a1bd766f9b3f090051ebfdfa864e160050e60c1930838db5b","citation_candidates":[{"source":"Matt. 15:39","passage":"mat-15","verse":39,"ref":"mat-15:39","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Mark 8:10","passage":"mrk-8","verse":10,"ref":"mrk-8:10","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"갈릴리의 성읍으로 마태복음에만 나오며, 막달라 마리아의 출생지입니다."},{"candidate_id":"ATLBC-CAND-0059","name_en":"Mahanaim","name_ko":"마하나임","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAHANAIM","ko":"마하나임. Mahanaim\n“두 진영”이라는 뜻이다. 요단 건너편 얍복 강 가까이의 곳으로, 야곱이 밧단아람에서 돌아올 때 “하나님의 사자들”을 만나 자기 일행을 “두 떼”로 나눈 곳이다(창 32:2). 이 이름은 후에 그곳에 세워진 성읍에 붙여졌다. 바산의 남쪽 경계였고(수 13:26, 30) 레위 사람의 성읍이 되었다(21:38). 여기서 사울의 아들 이스보셋이 다스렸는데(삼하 2:8, 12), 그동안 다윗은 헤브론에서 다스렸다. 또한 여기서 이스보셋은 어지러운 치세 끝에 자기 호위대의 두 사람에게 살해되었고(삼하 4:5-7), 그들은 그의 머리를 헤브론의 다윗에게 가져왔으나 상을 받기는커녕 잔인한 살인으로 그에게 죽임을 당했다. 이로부터 여러 해 뒤 아들 압살롬의 반역으로 예루살렘에서 도망할 때 다윗은 바르실래가 그를 대접한 마하나임을 본거지로 삼았고, 여기서 압살롬 주위에 모인 군대를 치러 갈 자기 군대를 점검했다. 그가 이 성읍의 성문에 앉아 있을 때, 두 군대 사이의 크고 결정적인 전투와 아들 압살롬의 죽음에 대한 소식이 그에게 도착했고, 그는 극심한 슬픔에 잠겼다(삼하 17:24-27).\n\n마하나임에 대한 유일한 다른 언급은 솔로몬의 관리 가운데 한 사람의 주둔지로서이다(왕상 4:14). 브니엘 가까이, 얍복 강 남쪽, 에스살트 북동쪽의 엘부키아, 곧 “작은 골짜기”라는 움푹한 평야에서 발견된 폐허인 지금의 무쿠마로 비정되었다.","source_sha256":"3602d64abdfb67f4a47956f3ee5eb745bf41463c45e131ada5334bbf6aaeb1c0","citation_candidates":[{"source":"Gen. 32:2","passage":"gen-32","verse":2,"ref":"gen-32:2","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"Josh. 13:26","passage":"jos-13","verse":26,"ref":"jos-13:26","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"2 Sam. 2:8","passage":"2sa-2","verse":8,"ref":"2sa-2:8","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"2 Sam. 4:5-7","passage":"2sa-4","verse":5,"ref":"2sa-4:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 17:24-27","passage":"2sa-17","verse":24,"ref":"2sa-17:24","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"1 Kings 4:14","passage":"1ki-4","verse":14,"ref":"1ki-4:14","status":"KRV_VERIFIED","exact_korean_token":"마하나임"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“두 진영”이라는 뜻으로, 야곱이 하나님의 천사들을 만난 얍복 강 근처의 성읍이며 후에 레위 사람의 성읍이 되었습니다."},{"candidate_id":"ATLBC-CAND-0060","name_en":"Megiddo","name_ko":"므깃도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MEGIDDO","ko":"므깃도. Megiddo\n“군대의 곳”이라는 뜻이다. 본래 가나안 사람의 왕성 가운데 하나였고(수 12:21) 므낫세 지파에 속했으나(삿 1:27), 솔로몬 때(왕상 4:12; 9:15)에야 이스라엘 사람이 완전히 차지한 듯하다.\n\n므깃도 골짜기 곧 평야는 팔레스타인의 큰 전쟁터인 에스드라엘론 평야의 일부였다. 여기서 바락이 하솔 왕 야빈에게 뚜렷한 승리를 거두었는데, 그의 장군 시스라가 적군을 이끌었다. 바락은 북쪽 지파의 용사들을 모으고 여선지자 드보라(참조)의 격려를 받아 큰 평야에서 가나안 사람을 쳤다. 시스라의 군대는 완전히 혼란에 빠져, 물이 불어 둑을 넘친 기손 강물에 삼켜졌다(삿 4:5).\n\n이로부터 여러 해 뒤(주전 610년) 바로 느고 2세가 앗수르 왕을 치러 가는 길에 블레셋과 샤론 평야를 지나갔다. 요시야 왕은 므깃도 평야에서 그의 진군을 막으려다 이집트 사람에게 패했다. 그는 전투에서 부상을 입고 병거에 실려 예루살렘으로 가는 도중에 죽었고(왕하 23:29; 대하 35:22-24), 온 이스라엘이 그를 위해 애곡했다. 이 애곡이 너무 보편적이고 쓰라려서 속담이 되었고 스가랴(12:11-12)가 이를 암시한다. 므깃도는 갈멜 산 북동쪽 이마 아래, 에스드라엘론 평야 남서쪽 가장자리, 이스르엘에서 서쪽으로 9마일, 기손 강 어귀에 있는 지금의 엘레준으로 비정되었다. 다른 이들은 벧산 남서쪽 4마일의 무제다로 비정하지만 그 터에 대한 문제는 아직 정해지지 않았다.","source_sha256":"853b0f2ade4e9cee6e131cf7c34e98026b648bd77ccae3b0c57efe68298779d6","citation_candidates":[{"source":"Josh. 12:21","passage":"jos-12","verse":21,"ref":"jos-12:21","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"Judg. 1:27","passage":"jdg-1","verse":27,"ref":"jdg-1:27","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"1 Kings 4:12","passage":"1ki-4","verse":12,"ref":"1ki-4:12","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"Judg. 4:5","passage":"jdg-4","verse":5,"ref":"jdg-4:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 23:29","passage":"2ki-23","verse":29,"ref":"2ki-23:29","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"2 Chr. 35:22-24","passage":"2ch-35","verse":22,"ref":"2ch-35:22","status":"KRV_VERIFIED","exact_korean_token":"므깃도"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“군대의 곳”이라는 뜻의 가나안 왕성으로, 에스드라엘론 평야의 큰 싸움터에 있었습니다."},{"candidate_id":"ATLBC-CAND-0061","name_en":"Miletus","name_ko":"밀레도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MILETUS","ko":"밀레도. Miletus\n(딤후 4:20의 밀레도 Miletum) 항구 도시로 고대 이오니아의 수도였으며 에베소에서 남쪽으로 약 36마일에 있다. 바울은 그리스에서 수리아로 가는 항해 중에 이 항구에 들러, 행 20:15-35에 기록된 에베소 장로들(28절의 “감독자”)에게 고귀하고 애절한 연설을 했다. 밀레도의 터는 지금 해안에서 10마일쯤 떨어져 있다. (에베소서 항목 참조.)","source_sha256":"3f01451cecc3134f1280ee640aea5dc6a60e6d12462ea7649bc7b413d9d62764","citation_candidates":[{"source":"2 Tim. 4:20","passage":"2ti-4","verse":20,"ref":"2ti-4:20","status":"KRV_VERIFIED","exact_korean_token":"밀레도"},{"source":"Acts 20:15-35","passage":"act-20","verse":15,"ref":"act-20:15","status":"KRV_VERIFIED","exact_korean_token":"밀레도"}],"status":"READER_REFERENCE_ONLY","intro_ko":"에베소 남쪽 약 36마일의 이오니아 항구 도시로, 바울이 에베소 장로들에게 감동적인 작별 설교를 한 곳입니다."},{"candidate_id":"ATLBC-CAND-0063","name_en":"Nain","name_ko":"나인","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-NAIN","ko":"나인. Nain\n(히브리어 나임에서, “푸른 초장”, “사랑스러운”) 예수께서 그 성문 가까이에서 과부의 아들을 살리신 성읍의 이름이다(눅 7:11-17). 제벨 에드두히(= “모레 산” = “작은 헤르몬”)의 북서쪽 비탈에 서 있는 네인이라는 마을로 비정되며, 다볼에서 약 4마일, 가버나움에서 남서쪽으로 25마일 떨어져 있다. 이 마을이 서 있는 비탈 기슭에 에스드라엘론의 큰 평야가 있다.\n\n이것은 우리 주님이 행하신 죽은 자를 살리는 첫 번째 기적이었고, 사람들에게 큰 경외와 놀라움을 불러일으켰다.","source_sha256":"bcaadeca830a36b3ac1b091e22d6b61512330760cd6adaafd4ca3ebed3240ec4","citation_candidates":[{"source":"Luke 7:11-17","passage":"luk-7","verse":11,"ref":"luk-7:11","status":"KRV_VERIFIED","exact_korean_token":"나인"}],"status":"READER_REFERENCE_ONLY","intro_ko":"예수께서 성문 가까이에서 과부의 아들을 살리신 성읍으로, 다볼 산 서남쪽에 있습니다."},{"candidate_id":"ATLBC-CAND-0066","name_en":"Patmos","name_ko":"밧모","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PATMOS","ko":"밧모. Patmos\n에게 해 “스포라데스”라 불리는 섬 무리 가운데 하나인 작고 바위가 많고 메마른 섬이다. 성경에는 계 1:9에서만 언급된다. 요한이 황제 도미티아누스(주후 95년)에게 유배된 이 섬에서 그는 자기 책에 기록된 놀라운 계시를 하나님께 받았다. 이로써 이곳은 모든 시대에 가장 깊은 관심의 대상이 되었다. 지금은 파트모라 불린다. (요한 항목 참조.)","source_sha256":"45e7f4bac86bb37d4f56f2a32c72a2c1368979a4f61772232057a1ee6618b67c","citation_candidates":[{"source":"Rev. 1:9","passage":"rev-1","verse":9,"ref":"rev-1:9","status":"KRV_VERIFIED","exact_korean_token":"밧모"}],"status":"READER_REFERENCE_ONLY","intro_ko":"에게 해 스포라데스 제도의 작고 메마른 바위섬으로, 사도 요한이 유배되어 계시를 받은 곳입니다."},{"candidate_id":"ATLBC-CAND-0068","name_en":"Pergamos","name_ko":"버가모","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PERGAMOS","ko":"버가모. Pergamos\n소아시아 무시아의 주요 성읍이다. “일곱 교회” 가운데 하나가 이곳에 세워졌다(계 1:11; 2:17). 악함으로 유명하여 우리 주님이 “사탄의 권좌”가 그곳에 있다고 말씀하실 정도였다. 버가모 교회는 진리에서 벗어나 발람의 교훈과 니골라당의 교훈을 받아들인 일로 책망을 받았다. 그리스도의 “충성된 증인” 안디바가 여기서 자기 피로 증언을 인쳤다.\n\n이 성은 카이쿠스 강변에 있었고 바다에서 약 20마일 떨어져 있었다. 지금은 베르가마라 불리며 인구가 약 2만 명인데 그중 약 2천 명이 그리스도인이라고 한다. 양피지(참조)가 처음 여기서 만들어졌고, 헬라인이 이 성의 이름을 따 페르가메네라 불렀다.","source_sha256":"feff32cd0c3a1c0dd81e826e03606b898f3eea757e3e5a294b7413867226ff18","citation_candidates":[{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"버가모"}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아 무시아의 주요 성읍으로, 요한계시록의 일곱 교회 가운데 하나가 세워진 곳입니다."},{"candidate_id":"ATLBC-CAND-0069","name_en":"Philadelphia","name_ko":"빌라델비아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PHILADELPHIA","ko":"빌라델비아. Philadelphia\n“형제 사랑”이라는 뜻이다. 소아시아 루디아의 성읍으로 사데에서 남동쪽으로 약 25마일이다. “일곱 교회” 가운데 하나가 있던 곳이다(계 3:7-12). 주후 1392년에 터키 사람의 소유가 되었다. 지진으로 여러 번 거의 파괴되었다. 지금도 상당한 크기의 성읍으로 알라셰히르, 곧 “하나님의 성”이라 불린다.","source_sha256":"be03d1d85d282e5550abd96bb6eb4ccd3fe0282caca34796fb50eee7fd647506","citation_candidates":[{"source":"Rev. 3:7-12","passage":"rev-3","verse":7,"ref":"rev-3:7","status":"KRV_VERIFIED","exact_korean_token":"빌라델비아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“형제 사랑”이라는 뜻으로, 사데 남동쪽 약 25마일의 루디아 성읍이며 일곱 교회 가운데 하나가 있던 곳입니다."},{"candidate_id":"ATLBC-CAND-0070","name_en":"Philippi","name_ko":"빌립보","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PHILIPPI","ko":"빌립보. Philippi\n(1) 전에는 크레니데스, 곧 “샘”이라 불렸으며 마게도냐 속주의 수도이다. 바다 머리 가까이에 있었고 카발라에서 북서쪽으로 약 8마일이다. 지금은 필리베직이라는 폐허가 된 마을이다. 마게도냐의 필리포스가 옛 트라키아 성읍 크레니데스를 요새화하고 자기 이름을 따 빌립보라 불렀다(주전 359-336년). 황제 아우구스투스 때 이 성은 로마 식민도시, 곧 새로 정복한 지역을 통제하려고 로마 병사들을 정착시킨 군사 정착지가 되었다. 로마의 도시법을 따르는 “작은 로마”였고, 로마에서 직접 임명한 두움비리라는 군 장교들이 다스렸다. 섭리의 인도로 그곳에 이른 바울과 그의 동행자 실라가 여기서 복음을 전하여 유럽 최초의 교회를 세웠다. (루디아 항목 참조.) 이 성공이 사람들의 적의를 일으켜 그들은 “부끄러운 대우”를 받았다(행 16:9-40; 살전 2:2). 바울과 실라는 마침내 이 성을 떠나 암비볼리(참조)로 갔다.\n\n(2) 분봉왕 빌립, 곧 헤롯의 아들이 왕국 북부의 통치를 이어받았을 때, 그는 바니아스 성을 확장하여 황제를 기려 가이사랴라 불렀다. 그러나 해안의 가이사랴와 구별하려고 후에 자기 이름을 더하여 가이사랴 빌립보(참조)라 불렀다.","source_sha256":"865792105c4de322798a7b0e2e82b22c7d3c2326fdbf1db5f040b51602171b8d","citation_candidates":[{"source":"Acts 16:9-40","passage":"act-16","verse":9,"ref":"act-16:9","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Thess. 2:2","passage":"1th-2","verse":2,"ref":"1th-2:2","status":"KRV_VERIFIED","exact_korean_token":"빌립보"}],"status":"READER_REFERENCE_ONLY","intro_ko":"마게도냐 지방의 주요 도시로, 바울이 유럽에서 처음 복음을 전해 교회가 세워진 곳입니다."},{"candidate_id":"ATLBC-CAND-0071","name_en":"Pisidia","name_ko":"비시디아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PISIDIA","ko":"비시디아. Pisidia\n소아시아의 지방으로 밤빌리아 북쪽에 있다. 타우루스 산맥이 이를 가로지른다. 이 지방의 주요 성읍 가운데 하나인 안디옥을 바울이 두 번 방문했다(행 13:14; 14:21-24).","source_sha256":"d1e29e4fa3026f63fc31733e5c34cdc4e8fb1a2c3ba9228402f19312dcf0132e","citation_candidates":[{"source":"Acts 13:14","passage":"act-13","verse":14,"ref":"act-13:14","status":"KRV_VERIFIED","exact_korean_token":"비시디아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아에서 밤빌리아 북쪽의 지방으로, 바울이 방문한 안디옥이 주요 성읍이었습니다."},{"candidate_id":"ATLBC-CAND-0072","name_en":"Ptolemais","name_ko":"돌레마이","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PTOLEMAIS","ko":"돌레마이. Ptolemais\n갈릴리의 해안 성읍이다(행 21:7). 본래 “악고”(참조)라 불렸으며, 프톨레마이오스 소테르가 코일레시리아를 차지했을 때 프톨레마이스라는 이름을 얻었다.","source_sha256":"8ca1c973e5898d96501749635e945804613b43c6ef77b2f773d79316011bbd62","citation_candidates":[{"source":"Acts 21:7","passage":"act-21","verse":7,"ref":"act-21:7","status":"KRV_VERIFIED","exact_korean_token":"돌레마이"}],"status":"READER_REFERENCE_ONLY","intro_ko":"갈릴리의 해안 성읍으로 본래 “악고”라 불렸고, 프톨레마이오스에게서 이름을 받았습니다."},{"candidate_id":"ATLBC-CAND-0073","name_en":"Puteoli","name_ko":"보디올","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PUTEOLI","ko":"보디올. Puteoli\n캄파니아 해안의 성읍으로, 나폴리 만에서 북쪽으로 뻗은 만의 북쪽 기슭에 있다. 바울이 로마로 가는 길에 상륙한 곳이며 로마까지는 170마일이었다. 여기서 바울은 이레를 머물렀다(행 28:13-14). 알렉산드리아 곡물선의 큰 집산지였다. 여기서 바울과 일행이 “아피아 가도”를 따라 로마로 가는 여정을 시작했다. 지금은 포추올리라 불린다. 거대한 원형 경기장과 바울이 상륙한 부두의 유적을 지금도 볼 수 있다.","source_sha256":"781a3cc1814dbeaf698f6a51e9db754d88ee0cd9a02a69774eb18668f0ea77d6","citation_candidates":[{"source":"Acts 28:13","passage":"act-28","verse":13,"ref":"act-28:13","status":"KRV_VERIFIED","exact_korean_token":"보디올"}],"status":"READER_REFERENCE_ONLY","intro_ko":"이탈리아 캄파니아 해안의 도시로, 바울이 로마로 가는 길에 상륙해 이레를 머문 곳입니다."},{"candidate_id":"ATLBC-CAND-0074","name_en":"Rabbah","name_ko":"랍바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-RABBAH","ko":"랍바. Rabbah\n또는 랍밧, “큰”이라는 뜻이다. (1) “암몬 자손의 랍바”는 암몬 사람의 주요 성읍으로, 요단 동쪽 약 20마일의 동쪽 구릉 지대, 얍복 강과 합류하는 두 시내 가운데 남쪽 시내 가에 있다. 여기에 옥의 침대가 보존되어 있었는데(신 3:11), 아마 암몬 사람이 바산 왕에게 거둔 어떤 승리의 전리품이었을 것이다. 다윗이 큰 전쟁에서 그들의 모든 동맹을 굴복시킨 뒤 요압에게 강한 군대를 주어 그들의 성을 치게 했다. 이 성은 이 년 동안 공격자에 맞서 버텼다. 군대가 이 오랜 포위에 몰두해 있을 때 다윗이 그의 인격에 얼룩을 남기고 여생에 어둠을 드리운 그 수치스러운 행위를 저질렀다. 마침내 “왕의 성”(또는 “물들의 성”, 삼하 12:27, 곧 성채와 구별되는 강가의 아랫성)을 점령한 요압은 마지막 공격을 지휘하도록 다윗을 불렀다(11:1; 12:26-31). 이 성은 약탈에 넘겨졌고 주민은 무자비하게 죽임을 당했으며 “암몬 자손의 모든 성읍에 그렇게 했다.” 랍바의 멸망은 다윗의 마지막 정복이었다. 그의 왕국은 이제 가장 먼 한계에 이르렀다(삼하 8:1-15; 대상 18:1-15). 이 성의 점령은 아모스(1:14), 예레미야(49:2-3), 에스겔(21:20; 25:5)에게서 언급된다.\n\n(2) 유다 산지의 성읍이다(수 15:60). 아마 베이트지브린에서 북동쪽 6마일의 폐허 룹바일 것이다.","source_sha256":"c36df7c58fb916fe3434b5567b6e4b89d26abf85b2103234b0b4d51638b15f7f","citation_candidates":[{"source":"Deut. 3:11","passage":"deu-3","verse":11,"ref":"deu-3:11","status":"KRV_VERIFIED","exact_korean_token":"랍바"},{"source":"2 Sam. 12:27","passage":"2sa-12","verse":27,"ref":"2sa-12:27","status":"KRV_VERIFIED","exact_korean_token":"랍바"},{"source":"2 Sam. 8:1-15","passage":"2sa-8","verse":1,"ref":"2sa-8:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 18:1-15","passage":"1ch-18","verse":1,"ref":"1ch-18:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 15:60","passage":"jos-15","verse":60,"ref":"jos-15:60","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“큰 성”이라는 뜻으로, 암몬 사람의 주된 성읍이며 요단 동쪽 구릉 지대에 있었습니다."},{"candidate_id":"ATLBC-CAND-0075","name_en":"Ramoth-gilead","name_ko":"길르앗 라못","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-RAMOTH-GILEAD","ko":"길르앗 라못. Ramoth-gilead\n“길르앗의 높은 곳”이라는 뜻이며 요단 동쪽의 도피성이다. “길르앗 라못”(신 4:43; 수 20:8; 21:38)이라 불린다. 아합은 여호사밧과 함께 수리아 왕의 손에서 이곳을 구하려다 치명상을 입었다(왕상 22:1-36). 후에 아하시야와 요람이 비슷한 시도를 했고 요람이 부상을 입었다(왕하 8:28). 이 성에서 여호사밧의 아들 예후가 선지자의 생도 가운데 한 사람에게 기름 부음을 받았다(9:1, 4).\n\n데가볼리의 성읍 가운데 하나인 게라사 곧 제라시에서 서쪽으로 약 5마일, 얍복 강 북쪽 비탈의 레이문으로 비정하는 것이 개연성이 있다. 다른 이들은 에스살트 북동쪽 약 25마일의 게로시로 비정하며, 많은 이가 이곳과도 동일시했다. (라맛 미스베 항목 참조.)","source_sha256":"714b5dcf3e978cad5532fd8cc6d49edb7f1cf25c3b40d39eac6d70ad8a4f014b","citation_candidates":[{"source":"Deut. 4:43","passage":"deu-4","verse":43,"ref":"deu-4:43","status":"KRV_VERIFIED","exact_korean_token":"길르앗 라못"},{"source":"Josh. 20:8","passage":"jos-20","verse":8,"ref":"jos-20:8","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 22:1-36","passage":"1ki-22","verse":1,"ref":"1ki-22:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 8:28","passage":"2ki-8","verse":28,"ref":"2ki-8:28","status":"KRV_VERIFIED","exact_korean_token":"길르앗 라못"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“길르앗의 높은 곳”이라는 뜻으로, 요단 동쪽의 도피성이며 아합이 치명상을 입은 곳입니다."},{"candidate_id":"ATLBC-CAND-0079","name_en":"Salamis","name_ko":"살라미","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SALAMIS","ko":"살라미. Salamis\n키프로스 섬 남동 해안의 성읍이다(행 13:5). 사울과 바나바가 첫 전도 여행 때 그곳에 여러 곳이 있었던 듯한 유다 회당 가운데 하나에서 말씀을 전했다. 지금은 파마구스타라 불린다.","source_sha256":"7cb1ba7555768570c0989b04f7f1a151d08f70753f0dc9c323f8d83b936d90ff","citation_candidates":[{"source":"Acts 13:5","passage":"act-13","verse":5,"ref":"act-13:5","status":"KRV_VERIFIED","exact_korean_token":"살라미"}],"status":"READER_REFERENCE_ONLY","intro_ko":"키프로스 섬 남동 해안의 성읍으로, 바울과 바나바가 첫 전도 여행 때 유다 회당에서 말씀을 전한 곳입니다."},{"candidate_id":"ATLBC-CAND-0080","name_en":"Sardis","name_ko":"사데","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SARDIS","ko":"사데. Sardis\n소아시아 루디아의 수도이다. 토몰로스 산 기슭의 팍톨로스 강변에 있었다. 아시아의 일곱 교회 가운데 하나가 여기 있었다(계 3:1-6). 지금은 세르트칼레시라는 폐허이다.","source_sha256":"2c25b66fa4125f66f67d41d508143c5862dba87c17a20445e9a7da73dbb027db","citation_candidates":[{"source":"Rev. 3:1-6","passage":"rev-3","verse":1,"ref":"rev-3:1","status":"KRV_VERIFIED","exact_korean_token":"사데"}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아 루디아의 중심 도시로, 요한계시록의 일곱 교회 가운데 하나가 있던 곳입니다."},{"candidate_id":"ATLBC-CAND-0081","name_en":"Smyrna","name_ko":"서머나","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SMYRNA","ko":"서머나. Smyrna\n“몰약”이라는 뜻이다. 소아시아 서해안의 고대 이오니아 성읍으로 에베소에서 북쪽으로 약 40마일에 있다. 지금은 아나톨리아의 주요 도시로 혼합된 인구가 약 20만 명이며 그중 약 삼분의 일이 그리스도인이라 공언한다. 여기에 세워진 교회는 우리 주님이 편지하신 일곱 교회 가운데 하나였다(계 2:8-11). 사도 요한의 제자인 유명한 폴리카르포스가 2세기에 서머나 교회의 걸출한 지도자였다. 그는 여기서 주후 155년에 순교했다.","source_sha256":"38cde8df83783acf259c2158556b736f0437ab95b904bed776cd2a6c83046f9a","citation_candidates":[{"source":"Rev. 2:8-11","passage":"rev-2","verse":8,"ref":"rev-2:8","status":"KRV_VERIFIED","exact_korean_token":"서머나"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“몰약”이라는 뜻으로, 에베소 북쪽 약 40마일 소아시아 서해안의 이오니아 성읍이며 일곱 교회 가운데 하나가 있었습니다."},{"candidate_id":"ATLBC-CAND-0082","name_en":"Succoth","name_ko":"숙곳","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SUCCOTH","ko":"숙곳. Succoth\n“초막들”이라는 뜻이다. (1) 이스라엘 사람이 라암셋을 떠난 뒤 처음 진을 친 곳이다(출 12:37). 비돔(참조)의 민간 이름이다.\n\n(2) 요단 동쪽의 성읍으로, 얍복 강 북쪽 평야에서 그 강에서 약 1마일 떨어진 높은 둔덕이자 잔해 더미인 텔 다르알라로 비정된다(수 13:27). 야곱은 밧단아람에서 돌아오는 길에 에서를 만난 뒤 여기서(창 32:17, 30; 33:17) 자기를 위해 집을 짓고 가축을 위해 초막을 만들었다. 이 성의 방백들은 기드온과 그의 삼백 명이 길보아의 큰 승리 뒤에 달아나는 미디안 사람 무리 가운데 하나를 “피곤하나 추격하며” 올 때 무례하게도 도움을 주기를 거절했다. 이 무리를 칼골에서 따라잡아 무찌른 뒤 돌아오는 길에 기드온은 이 성의 지도자들을 혹독하게 벌했다. “그는 성읍의 장로들을 잡고 광야의 가시와 찔레를 가져다 그것으로 숙곳 사람들을 가르쳤다”(삿 8:13-16). 이곳에 성전의 놋 기구를 주조하는 주조소가 세워졌다(왕상 7:46).","source_sha256":"b370fad427a7536099957243739971b1418663aae70eb377660f617370bf2ac7","citation_candidates":[{"source":"Josh. 13:27","passage":"jos-13","verse":27,"ref":"jos-13:27","status":"KRV_VERIFIED","exact_korean_token":"숙곳"},{"source":"Gen. 32:17","passage":"gen-32","verse":17,"ref":"gen-32:17","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 8:13-16","passage":"jdg-8","verse":13,"ref":"jdg-8:13","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 7:46","passage":"1ki-7","verse":46,"ref":"1ki-7:46","status":"KRV_VERIFIED","exact_korean_token":"숙곳"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“초막들”이라는 뜻으로, 출애굽 때 이스라엘의 첫 진영지와 야곱이 집을 지은 요단 동쪽 성읍을 가리킵니다."},{"candidate_id":"ATLBC-CAND-0083","name_en":"Sychar","name_ko":"수가","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SYCHAR","ko":"수가. Sychar\n“거짓말쟁이” 또는 “술꾼”이라는 뜻이다(사 28:1, 7 참조). 십자군 시대 이후 보통 수겜 곧 세겜(요 4:5)과 동일시되어 왔다. 그러나 이제는 최근의 탐사 결과로 에발 산 남쪽 기슭, 야곱의 우물에서 북쪽으로 약 1마일에 있는 작은 사마리아 성읍 아스카르로 비정되었다.","source_sha256":"c1bbb13d3baeb09943936b87629896e686975c335a63e6e23dbd29712a6f7e1c","citation_candidates":[{"source":"Isa. 28:1","passage":"isa-28","verse":1,"ref":"isa-28:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 4:5","passage":"jhn-4","verse":5,"ref":"jhn-4:5","status":"KRV_VERIFIED","exact_korean_token":"수가"}],"status":"READER_REFERENCE_ONLY","intro_ko":"요한복음 4장의 사마리아 성읍으로, 세겜 북쪽 약 1마일, 야곱의 우물 가까이로 비정됩니다."},{"candidate_id":"ATLBC-CAND-0085","name_en":"Tabor","name_ko":"다볼","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TABOR","ko":"다볼. Tabor\n“높은 곳”이라는 뜻이다. (1) 지금의 제벨 엣투르로, 갈릴리 바다에서 서쪽으로 11마일에 있는 원뿔 모양의 두드러진 산이다. 높이는 약 1,843피트이다. 그 꼭대기에서의 전망은 유달리 넓고 웅장하다고 한다. 이는 시 89:12와 렘 46:18에서 암시된다. 바락이 시스라(참조)와 싸우기 전에 진을 친 곳이 여기였다(삿 4:6-14). 이곳이 우리 주님이 변화하신 현장이라는 오래된 전승이 있으나 근거가 없다. (헤르몬 항목 참조.) “다볼은 북쪽 지파와 남쪽 지파, 산지와 중앙 평야의 경계 지대에 서서 두드러지고 외따로 있어서 모든 시대에 이름난 곳이 되었고, 시편 기자가 이를 헤르몬과 연결시키게 된 것이 분명하다. 하나는 남쪽, 하나는 북쪽을 상징한다.” 여전히 이곳이 변화산이었다고 주장하는 이들도 있다(변화 항목 참조).\n\n(2) 스불론의 성읍이다(대상 6:77).\n\n(3) “다볼 평지”(삼상 10:3)는 개정역처럼 “다볼 상수리나무”가 되어야 한다. 이곳은 아마 창 35:8의 알론바굿일 것이다.","source_sha256":"689f490411cccad95dacf8dab43e12a86db0d4b09b888bb249b360632c5580a2","citation_candidates":[{"source":"Ps. 89:12","passage":"psa-89","verse":12,"ref":"psa-89:12","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Jer. 46:18","passage":"jer-46","verse":18,"ref":"jer-46:18","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Judg. 4:6-14","passage":"jdg-4","verse":6,"ref":"jdg-4:6","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"1 Chr. 6:77","passage":"1ch-6","verse":77,"ref":"1ch-6:77","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"1 Sam. 10:3","passage":"1sa-10","verse":3,"ref":"1sa-10:3","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Gen. 35:8","passage":"gen-35","verse":8,"ref":"gen-35:8","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“높은 곳”이라는 뜻으로, 갈릴리 바다 서쪽 11마일의 원뿔 모양 산이며 바락이 시스라와 싸우기 전에 진을 친 곳입니다."},{"candidate_id":"ATLBC-CAND-0087","name_en":"Tarsus","name_ko":"다소","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TARSUS","ko":"다소. Tarsus\n길리기아의 주된 성읍이다. 부와 학문의 학교로 이름이 높았고, 그 점에서 아덴과 알렉산드리아에 맞섰으며 오히려 그들을 능가하여 “이름 없는 성읍이 아니다”라고 불렸다. 사도 바울의 출생지이다(행 21:39). 퀴드노스 강변에 있었고 지중해에서 북쪽으로 약 12마일이었다. 앗수르 왕 사르다나팔로스가 세웠다고 한다. 지금은 테르수스라 불리는 더럽고 허물어진 터키 마을이다. (바울 항목 참조.)","source_sha256":"649d9495b0c87c1560f38019edffc71fa5bb92304df314ed10637a20c8d6d471","citation_candidates":[{"source":"Acts 21:39","passage":"act-21","verse":39,"ref":"act-21:39","status":"KRV_VERIFIED","exact_korean_token":"다소"}],"status":"READER_REFERENCE_ONLY","intro_ko":"길리기아의 주된 성읍으로, 부와 학문으로 유명했고 사도 바울의 고향입니다."},{"candidate_id":"ATLBC-CAND-0088","name_en":"Thessalonica","name_ko":"데살로니가","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-THESSALONICA","ko":"데살로니가. Thessalonica\n테르마이코스 만에 있는 크고 인구 많은 도시이다. 마게도냐의 네 로마 구역 가운데 하나의 수도였고 법무관이 다스렸다. 이 도시를 세운 카산드로스의 아내 데살로니케의 이름을 따 불렸다. 그는 아버지 필리포스가 딸이 태어났다는 소식을 테살리아 사람에게 승리한 날 처음 들었기 때문에 이렇게 이름 지어졌다. 바울은 제2차 전도 여행 때 이 성의 회당, 곧 마게도냐 그 지역 유다 사람의 주된 회당에서 전도하여 교회의 기초를 놓았다(행 17:1-4; 살전 1:9). 유다 사람의 폭력이 그를 성에서 쫓아 그는 베뢰아로 도망쳤다(행 17:5-10). 유다 사람이 바울과 실라가 묵던 야손을 “끌고 간” 앞의 “성읍 관리들”은 원문에서 폴리타르카이라 불리는데, 이는 흔하지 않은 낱말이지만 데살로니가의 한 아치에 새겨진 것이 발견되었다. 이 발견은 역사가의 정확성을 확증한다. 바울은 후에 다시 이곳 교회를 방문했다(20:1-3). 이 성은 오랫동안 중요성을 유지했다. 지금은 살로니키라는 이름으로 유럽 쪽 터키에서 가장 중요한 성읍이며, 혼합된 인구가 약 85,000명이다.","source_sha256":"ffc976614ed0bfb21292eb515b6cb9c2862fa93f55e5ea21277541327d7fbc88","citation_candidates":[{"source":"Acts 17:1-4","passage":"act-17","verse":1,"ref":"act-17:1","status":"KRV_VERIFIED","exact_korean_token":"데살로니가"},{"source":"Acts 17:5-10","passage":"act-17","verse":5,"ref":"act-17:5","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"테르마이코스 만의 크고 인구 많은 도시로, 마게도냐의 네 로마 구역 가운데 하나의 수도였습니다."},{"candidate_id":"ATLBC-CAND-0089","name_en":"Thyatira","name_ko":"두아디라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-THYATIRA","ko":"두아디라. Thyatira\n소아시아의 성읍으로 루디아와 무시아의 경계에 있다. 현대 이름은 악히사르, 곧 “흰 성”이다. 일곱 교회 가운데 하나가 여기 있었다(계 1:11; 2:18-28). 자주 장사, 정확히는 이 색으로 물들인 천을 파는 루디아가 이 성 출신이었다(행 16:14). 염색으로 유명했고 지금도 그러하다. 폐허 가운데서 옛날 이 성의 염색공 조합에 관한 비문이 발견되었다.","source_sha256":"68667fdfb871706fb156d43bd39ad071eea08868519ae95a1d577f8ca2db21e1","citation_candidates":[{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"두아디라"},{"source":"Acts 16:14","passage":"act-16","verse":14,"ref":"act-16:14","status":"KRV_VERIFIED","exact_korean_token":"두아디라"}],"status":"READER_REFERENCE_ONLY","intro_ko":"리디아와 무시아 경계의 소아시아 성읍으로, 일곱 교회 가운데 하나가 있었고 자주 장사 루디아의 고향입니다."},{"candidate_id":"ATLBC-CAND-0091","name_en":"Troas","name_ko":"드로아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TROAS","ko":"드로아. Troas\n소아시아 북서쪽 무시아 해안의 성읍으로, 북쪽으로 조금(약 4마일) 떨어져 있던 옛 트로이의 이름을 따 불렸다. 여기서 바울은 제2차 전도 여행 때 “마게도냐 사람”이 나타나 “건너와서 우리를 도우라”고 말하는 환상을 보았다(행 16:8-11). 그는 다른 때에도 이곳을 방문했고, 그 방문 가운데 한 번은 겉옷과 책 몇 권을 이곳에 두고 갔다(고후 2:12; 딤후 4:13). 드로아의 폐허는 여러 마일에 걸쳐 있으며 그 터는 지금 대부분 상수리나무 숲으로 덮여 있다. 폐허의 현대 이름은 에스키 스탐불, 곧 “옛 콘스탄티노플”이다.","source_sha256":"14abf6d749e0b4548b8180e2d1965e6fb89d27d26127dea3349b3830eeef07cd","citation_candidates":[{"source":"Acts 16:8-11","passage":"act-16","verse":8,"ref":"act-16:8","status":"KRV_VERIFIED","exact_korean_token":"드로아"},{"source":"2 Cor. 2:12","passage":"2co-2","verse":12,"ref":"2co-2:12","status":"KRV_VERIFIED","exact_korean_token":"드로아"},{"source":"2 Tim. 4:13","passage":"2ti-4","verse":13,"ref":"2ti-4:13","status":"KRV_VERIFIED","exact_korean_token":"드로아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"소아시아 북서쪽 무시아 해안의 도시로, 바울이 “마게도냐 사람”의 환상을 본 곳입니다."},{"candidate_id":"ATLBC-CAND-0092","name_en":"Ur","name_ko":"우르","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-UR","ko":"우르. Ur\n“빛” 또는 “달의 도시”라는 뜻이다. “갈대아 사람의” 성읍이며 하란의 출생지이고(창 11:28, 31), 시날 곧 북부 갈대아에서 가장 큰 성읍이자 그 나라의 주된 상업 중심지이며 정치 권력의 중심이었다. 유프라테스 강 하구 가까이, 서안에 있었고, 역청으로 접합한 벽돌의 언덕인 엘무게이르, 곧 “역청 바른 곳” 또는 “역청의 성읍”으로 대표된다. 지금은 바다에서 150마일, 유프라테스 강에서 약 6마일 떨어져 있으며, 티그리스의 지류인 샤트 엘히에가 유프라테스에 합류하는 지점보다 조금 위쪽에 있다. 페르시아 만의 물이 이곳까지 내륙으로 들어와 있었으므로 예전에는 해양 도시였다. 우르는 바벨로니아의 항구여서, 만 연안의 주민과, 인도와 에티오피아와 이집트 같은 먼 나라와 교역이 이루어졌다. 주전 500년경에 버려졌으나 에렉처럼 오랫동안 큰 신성한 묘지 도시로 남았음이 그곳에서 발견된 무덤의 수에서 분명하다. (아브라함 항목 참조.)\n\n우리가 아는 가장 오래된 우르의 왕은 우르바우(“바우 여신의 종”, 홈멜의 읽기) 또는 우르구르(다른 이들의 읽기)이다. 그는 주전 2800년경 사람으로 우르 안에 있던 달의 신 신(Sin)의 유명한 신전을 짓는 일에 참여했다. 여기 실린 그림은 수메르어로 쓰여 우르 신전의 모든 벽돌에 찍힌 그의 쐐기문자 비문이며, 이렇게 읽는다. “우르의 왕 우르바우, 달의 신의 신전을 지은 이.”\n\n“우르는 바벨로니아의 달의 신 신(Sin)을 섬기는 일에 바쳐졌다. 그러나 이 영예를 다른 도시와 나누었고 그 도시가 하란(Harran)이다. 하란은 메소포타미아에 있었고, 동쪽에서 서쪽으로 그곳을 통과하는 큰길에서 이름을 얻었다. 이 이름은 바벨로니아어이며 바벨로니아 왕이 세웠음을 증언한다. 같은 증언은 그곳에서 바벨로니아의 달의 신에게 바친 숭배와 신의 옛 신전으로 더욱 결정적으로 입증된다. 사실 앗수르와 바벨로니아 세계에서 하란의 달의 신 신전은 우르의 달의 신 신전보다 아마 더 유명했을 것이다.\n\n“그러므로 우르와 하란 사이에는 초기에 긴밀한 관계가 있었음이 틀림없으며, 그 기록은 아직 복원되지 않았다. 아마 하란은 우르의 한 왕에게서 건설되었을 것이다. 어쨌든 두 도시는 같은 신에 대한 숭배로 묶여 있었는데, 이는 고대 세계에 존재한 가장 가깝고 가장 오래가는 연합의 끈이었다. 그러므로 데라가 우르에서 하란으로 이주했다는 것은 이상한 일이 아니게 된다. 그가 우르를 떠났다면 그곳이 가장 자연스러운 행선지였다. 신전의 한 뜰에서 다른 뜰로 옮겨 가는 것과 같았다.\n\n“성경 서술과 고고학 연구의 증거가 이렇게 놀랍게 들어맞는 것은 우연의 결과일 수 없다. 이 서술은 역사적이어야 한다. 훗날의 어떤 저자도, 바벨로니아 사람이었다 하더라도 지금 우리가 사실로 알고 있는 바와 이렇게 꼭 맞는 이야기를 지어낼 수 없었을 것이다. 이런 종류의 이야기가 팔레스타인 전승의 발명이었다는 것도 마찬가지로 불가능하다. 편견 없는 마음에게는, 데라가 우르에서 하란으로 이주한 역사가 사실에 근거한다는 결론을 피할 길이 없다.” (세이스)","source_sha256":"dc4b9e2ccdbb91fa5aeef4a8b49db0b422a49563b0acdd1357a6176c2253f29f","citation_candidates":[{"source":"Gen. 11:28","passage":"gen-11","verse":28,"ref":"gen-11:28","status":"KRV_VERIFIED","exact_korean_token":"우르"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“갈대아 사람의 우르”로 알려진 시날의 가장 큰 상업·정치 중심 도시이며 하란의 출생지입니다."},{"candidate_id":"ATLBC-CAND-0093","name_en":"Zarephath","name_ko":"사르밧","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZAREPHATH","ko":"사르밧. Zarephath\n“제련소”, 곧 “금속을 정련하고 녹이는 작업장”이라는 뜻이다. 두로와 시돈 사이 길의 거의 중간, 해안에서 약 1마일 떨어진 작은 페니키아 성읍으로 지금은 수라펜드이다. 엘리야는 “하늘이 삼 년 육 개월 동안 닫힌” “큰 기근” 때 여기서 가난한 과부와 함께 머물렀다(눅 4:26; 왕상 17:10). 신약에서는 사렙다라 불린다(눅 4:26).","source_sha256":"bcd0921cbe6d85fcf8ab389ace532518882854e7b7c8b1782aad6de338c58947","citation_candidates":[{"source":"Luke 4:26","passage":"luk-4","verse":26,"ref":"luk-4:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 17:10","passage":"1ki-17","verse":10,"ref":"1ki-17:10","status":"KRV_VERIFIED","exact_korean_token":"사르밧"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“제련소”라는 뜻으로, 두로와 시돈 사이 길의 작은 페니키아 성읍이며 엘리야가 가난한 과부와 지낸 곳입니다."},{"candidate_id":"ATLBC-CAND-0094","name_en":"Ziklag","name_ko":"시글락","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZIKLAG","ko":"시글락. Ziklag\n유다의 네게브, 곧 남쪽 땅의 성읍이다(수 15:31). 다윗이 모든 추종자와 함께 십에서 가드로 도망했을 때 블레셋 사람이 소유하고 있었다. 아기스 왕이 그에게 거처로 시글락을 주었다. 그는 거기서 일 년 넉 달 남짓 살았다. 이때부터 이 성은 유다 왕들에게 속했다(삼상 27:6). 다윗이 군대와 함께 이스라엘을 치러 가는 블레셋 원정에 합류하러 간 동안(29:11) 아말렉 사람에게 파괴되었다(30:1-2). 그러나 다윗이 그들을 추격하여 완전히 무찌르고 모든 포로를 돌려 보냈다(삼상 30:26-31). 이 원정에서 돌아온 지 이틀 후 다윗은 길보아의 참패와 사울의 죽음의 소식을 받았다(삼하 1:1-16). 그는 이제 시글락을 떠나 두 아내 아히노암과 아비가일, 육백 명의 부하와 함께 헤브론으로 돌아갔다. 브엘세바 남쪽의 폐허 더미 아슬루지로 비정되었다. 그러나 콘더는 이를 브엘세바 북서쪽 약 17마일, 블레셋과 유다와 아말렉의 경계에 있는 반 마일씩 떨어진 세 언덕 위의 폐허 쿠르벳 주헤일리카로 비정한다.","source_sha256":"de26e3075e7dacda4159cec6cd44d8255cb1966a9b4dc74b43b9081fbb8b70ea","citation_candidates":[{"source":"Josh. 15:31","passage":"jos-15","verse":31,"ref":"jos-15:31","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"1 Sam. 27:6","passage":"1sa-27","verse":6,"ref":"1sa-27:6","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"1 Sam. 30:26-31","passage":"1sa-30","verse":26,"ref":"1sa-30:26","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"2 Sam. 1:1-16","passage":"2sa-1","verse":1,"ref":"2sa-1:1","status":"KRV_VERIFIED","exact_korean_token":"시글락"}],"status":"READER_REFERENCE_ONLY","intro_ko":"유다 남부 네게브의 성읍으로, 블레셋 왕 아기스가 다윗에게 거처로 준 곳입니다."},{"candidate_id":"ATLBC-CAND-0095","name_en":"Zoar","name_ko":"소알","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZOAR","ko":"소알. Zoar\n“작은”이라는 뜻이다. 사해 동쪽 또는 남동쪽의 성읍으로, 롯과 그의 딸들이 소돔에서 도망해 간 곳이다(창 19:22-23). 본래 벨라라 불렸다(14:2, 8). 예언자 이사야(15:5)와 예레미야(48:34)가 이곳을 언급한다. 그 폐허는 지금도 케락 협곡 어귀에서 볼 수 있는데, 케락은 왕하 3장에 언급된 기르모압이며 지금의 텔 에쉬샤구르이다.","source_sha256":"44114bddd58531cdc9de7e879664c7fed92928f8c3fdfbda10edf5acb1c9f651","citation_candidates":[{"source":"Gen. 19:22","passage":"gen-19","verse":22,"ref":"gen-19:22","status":"KRV_VERIFIED","exact_korean_token":"소알"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“작은”이라는 뜻으로, 롯과 두 딸이 소돔에서 피신해 간 사해 동쪽 또는 남동쪽의 성읍입니다."},{"candidate_id":"ATLBC-CAND-0098","name_en":"Adullam","name_ko":"아둘람","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ADULLAM","ko":"아둘람. Adullam\n가나안 사람의 왕성 가운데 하나이며 지금의 아이드엘마이다(수 12:15; 15:35). 엘라 골짜기(참조)의 옛 로마 도로 위에 있었는데, 그곳은 다윗이 골리앗에게 거둔 기억할 만한 승리의 현장(삼상 17:2)이며 가드에서 멀지 않았다. 르호보암이 이집트에 맞서 요새화한 성읍들 가운데 하나였다(대하 11:7). “이스라엘의 영광”이라 불렸다(미 1:15).\n\n아둘람 굴은 다윗이 승리한 곳에서 남쪽으로 약 2마일, 베들레헴에서 서쪽으로 약 13마일에서 발견되었다. 이곳에는 높이 약 500피트의 언덕이 있어 수많은 동굴이 뚫려 있는데, 그중 하나에서 다윗은 “환난당한 자와 빚진 자와 마음이 원통한 자”(삼상 22:2) 모두를 모았다. 이 동굴 가운데 일부는 이삼백 명을 수용할 만큼 크다. 전승에 따르면 이 굴은 베들레헴과 사해 사이의 와디 쿠레이툰에 있었다고 하나, 이 견해는 잘 지지되기 어렵다.","source_sha256":"14a632595a415711f7b2f0c7153ab9631547d2809f178f6138abb0e2806e2487","citation_candidates":[{"source":"Josh. 12:15","passage":"jos-12","verse":15,"ref":"jos-12:15","status":"KRV_VERIFIED","exact_korean_token":"아둘람"},{"source":"1 Sam. 17:2","passage":"1sa-17","verse":2,"ref":"1sa-17:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Chr. 11:7","passage":"2ch-11","verse":7,"ref":"2ch-11:7","status":"KRV_VERIFIED","exact_korean_token":"아둘람"},{"source":"Micah 1:15","status":"UNSUPPORTED_BOOK"},{"source":"1 Sam. 22:2","passage":"1sa-22","verse":2,"ref":"1sa-22:2","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"가나안의 왕성 가운데 하나로, 엘라 골짜기에서 가드 가까이에 있었고 다윗이 피신한 굴이 있던 곳입니다."},{"candidate_id":"ATLBC-CAND-0099","name_en":"Aenon","name_ko":"애논","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AENON","ko":"애논. Aenon\n“샘들”이라는 뜻이다. 살림 가까이의 곳으로, 요한이 세례를 베푼 곳이다(요 3:23). 아마 에발 산에서 요단 강까지 뻗은 열린 골짜기 와디 파라의 윗수원 가까이였을 것이다. 샘이 가득하다. 샘에서 북쪽으로 4마일 떨어진 곳에서 아이눈이라는 곳이 발견되었다.","source_sha256":"8aeed89bdf7b25b4ac271f5e4083236b2cb737855fb216d84c6a882306412788","citation_candidates":[{"source":"John 3:23","passage":"jhn-3","verse":23,"ref":"jhn-3:23","status":"KRV_VERIFIED","exact_korean_token":"애논"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“샘들”이라는 뜻으로, 살림 가까이에서 요한이 세례를 베푼 곳입니다."},{"candidate_id":"ATLBC-CAND-0100","name_en":"Aroer","name_ko":"아로엘","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AROER","ko":"아로엘. Aroer\n“폐허”라는 뜻이다. (1) 아르논 강 북쪽 기슭의 성읍이다(신 4:48; 삿 11:26; 왕하 10:33). 시혼 왕국의 남쪽 경계였다(수 12:2). 지금은 아라이르라 불리며 사해에서 서쪽으로 13마일이다.\n\n(2) 갓 지파가 세운 성읍 가운데 하나로(민 32:34), 암몬의 수도 랍바 “앞”에 있었다(수 13:25). 입다의 역사(삿 11:33)와 다윗의 역사(삼하 24:5)에서 유명했다. (비교 사 17:2; 왕하 15:29.)\n\n(3) 유다 남쪽의 성읍으로 브엘세바에서 남동쪽으로 12마일이다. 다윗이 시글락에서 아말렉 사람에게서 노획물을 되찾은 뒤 선물을 보낸 곳이다(삼상 30:26, 28). 다윗의 용사 두 사람의 고향이다(대상 11:44). 지금은 아르아라라 불린다.","source_sha256":"d87291330e61442ae4da71ff988075ef9ae1613aeddf59480c4943928fbcd158","citation_candidates":[{"source":"Deut. 4:48","passage":"deu-4","verse":48,"ref":"deu-4:48","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Judg. 11:26","passage":"jdg-11","verse":26,"ref":"jdg-11:26","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Kings 10:33","passage":"2ki-10","verse":33,"ref":"2ki-10:33","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Josh. 12:2","passage":"jos-12","verse":2,"ref":"jos-12:2","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Num. 32:34","passage":"num-32","verse":34,"ref":"num-32:34","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Josh. 13:25","passage":"jos-13","verse":25,"ref":"jos-13:25","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Judg. 11:33","passage":"jdg-11","verse":33,"ref":"jdg-11:33","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Sam. 24:5","passage":"2sa-24","verse":5,"ref":"2sa-24:5","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Isa. 17:2","passage":"isa-17","verse":2,"ref":"isa-17:2","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Kings 15:29","passage":"2ki-15","verse":29,"ref":"2ki-15:29","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 30:26","passage":"1sa-30","verse":26,"ref":"1sa-30:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 11:44","passage":"1ch-11","verse":44,"ref":"1ch-11:44","status":"KRV_VERIFIED","exact_korean_token":"아로엘"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“폐허”라는 뜻으로, 아르논 강 북쪽의 시혼 왕국 남쪽 경계 성읍과, 갓 지파가 세운 암몬 수도 랍바 앞의 성읍을 가리킵니다."},{"candidate_id":"ATLBC-CAND-0101","name_en":"Bethphage","name_ko":"벳바게","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-PHAGE","ko":"벳바게. Bethphage\n“덜 익은 무화과의 집”이라는 뜻이다. 감람산 위의 마을로, 예루살렘에서 여리고로 가는 길에 있으며(마 21:1; 막 11:1; 눅 19:29) 베다니와 아주 가깝다. 예루살렘에서 안식일에 걸을 수 있는 거리의 한계, 곧 2,000규빗이었다. 지금의 케프르 엣투르로 비정되었다.","source_sha256":"7703902376b33a19f3f8769f38d54e6a1fb43012e064e0bb1969b34f5f2a06b3","citation_candidates":[{"source":"Matt. 21:1","passage":"mat-21","verse":1,"ref":"mat-21:1","status":"KRV_VERIFIED","exact_korean_token":"벳바게"},{"source":"Mark 11:1","passage":"mrk-11","verse":1,"ref":"mrk-11:1","status":"KRV_VERIFIED","exact_korean_token":"벳바게"},{"source":"Luke 19:29","passage":"luk-19","verse":29,"ref":"luk-19:29","status":"KRV_VERIFIED","exact_korean_token":"벳바게"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“덜 익은 무화과의 집”이라는 뜻으로, 감람산 위 베다니와 아주 가까운 마을입니다."},{"candidate_id":"ATLBC-CAND-0102","name_en":"Berea","name_ko":"베뢰아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BEREA","ko":"베뢰아. Berea\n마게도냐의 성읍으로, 바울이 데살로니가에서 박해를 받을 때 실라와 디모데와 함께 간 곳이다(행 17:10, 13). 이곳에서도 물러나야 하여 해안으로 도망쳐 거기서 아덴으로 배를 탔다(14-15절). 바울의 동행자 소바더가 이 성 출신이며 그의 회심은 아마 이때 일어났을 것이다(행 20:4). 지금은 베리아라 불린다.","source_sha256":"2b69fc9701197b07f1e0d9528357fd0ca6eda1b1f200c1bf86b536cd5d815694","citation_candidates":[{"source":"Acts 17:10","passage":"act-17","verse":10,"ref":"act-17:10","status":"KRV_VERIFIED","exact_korean_token":"베뢰아"},{"source":"Acts 20:4","passage":"act-20","verse":4,"ref":"act-20:4","status":"KRV_VERIFIED","exact_korean_token":"베뢰아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"마게도냐의 성읍으로, 바울이 데살로니가에서 박해를 받아 실라와 디모데와 함께 간 곳입니다."},{"candidate_id":"ATLBC-CAND-0103","name_en":"Bithynia","name_ko":"비두니아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BITHYNIA","ko":"비두니아. Bithynia\n소아시아의 속주로 흑해(유크시노스)와 프로폰티스 남쪽에 있다. 이곳에는 일찍부터 기독교 회중이 세워졌다(벧전 1:1). 바울은 성령께 막혀 이 속주에 들어가지 못했다(행 16:7). 교회사에서는 플리니우스가 로마 총독으로 다스린 속주로 유명한데, 그는 그리스도인이라는 신분과 행실 때문에 자기 법정에 끌려온 수많은 그리스도인에 대해 어떻게 해야 할지 난감하여 황제 트라야누스에게 지시를 청하는 편지를 썼다(주후 107년).","source_sha256":"e6e1c15902a1cb2bb8635447d5befe989faf3a353ac30b8e49d8786c6fa2a2fe","citation_candidates":[{"source":"1 Pet. 1:1","passage":"1pe-1","verse":1,"ref":"1pe-1:1","status":"KRV_VERIFIED","exact_korean_token":"비두니아"},{"source":"Acts 16:7","passage":"act-16","verse":7,"ref":"act-16:7","status":"KRV_VERIFIED","exact_korean_token":"비두니아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"흑해와 프로폰티스 남쪽의 소아시아 속주로, 일찍부터 기독교 회중이 있었지만 바울은 성령께 막혀 들어가지 못했습니다."},{"candidate_id":"ATLBC-CAND-0106","name_en":"Dor","name_ko":"돌","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DOR","ko":"돌. Dor\n“거처”라는 뜻이다. 로마인의 도라이며, 가나안 사람의 옛 왕성이다(수 11:1-2; 12:23). 시리아 해안에서 페니키아 사람이 사는 가장 남쪽의 정착지였다. 원래의 주민은 다윗에게 조공을 바치게 되었으나 한 번도 쫓겨나지 않은 듯하다. 솔로몬의 행정 구역 가운데 하나였다(삿 1:27; 왕상 4:11). 탄투라로 비정되었는데(탑이 탄투르, 곧 “뿔”과 비슷하다고 여겨 그렇게 이름 붙여짐), 이 탑은 1895년에 무너져 지금은 잔해와 옛 십자군 요새의 기초 벽만 남아 있다. 가이사랴에서 북쪽으로 약 8마일에 있으며 “벌거벗은 바닷가의 초라한 오두막으로 이루어진 슬프고 병든 작은 마을”이다.","source_sha256":"19b00d8b7c4474cdddc856f7af00174aa5bb059189a83f8ededc5f627c7cf372","citation_candidates":[{"source":"Josh. 11:1","passage":"jos-11","verse":1,"ref":"jos-11:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 1:27","passage":"jdg-1","verse":27,"ref":"jdg-1:27","status":"KRV_VERIFIED","exact_korean_token":"돌"},{"source":"1 Kings 4:11","passage":"1ki-4","verse":11,"ref":"1ki-4:11","status":"KRV_VERIFIED","exact_korean_token":"돌"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“거처”라는 뜻의 가나안 왕성으로, 시리아 해안에서 페니키아 사람이 사는 가장 남쪽 정착지였습니다."},{"candidate_id":"ATLBC-CAND-0107","name_en":"Ebal","name_ko":"에발","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EBAL","ko":"에발. Ebal\n“돌 많은”이라는 뜻이다. (1) 해발 3,076피트, 골짜기에서 1,200피트 높은 산으로, 그 북쪽에 세겜(참조) 성이 서 있었다. 이 산에는 여섯 지파가 서도록 정해졌고(신 27:12-13), 레위 사람이 율법을 읽는 골짜기에서 선포된 저주에 정해진 형식대로 응답했다(11:29; 29:4, 13). 이 산은 여호와를 위해 세운 첫 큰 제단의 터이기도 했다(신 27:5-8; 수 8:30-35). 그 후 에발이라는 이름은 유다 역사에 다시 나오지 않는다. (그리심 항목 참조.)\n\n(2) 에벨의 후손이다(대상 1:22). 오발(창 10:28)이라고도 한다.\n\n(3) 호리 사람 세일의 후손이다(창 36:23).","source_sha256":"d39f8cdc4f65be6598f60d881b95e2f30d251308e5e98d28c7bd677ef32b0e5a","citation_candidates":[{"source":"Deut. 27:12","passage":"deu-27","verse":12,"ref":"deu-27:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Deut. 27:5-8","passage":"deu-27","verse":5,"ref":"deu-27:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 8:30-35","passage":"jos-8","verse":30,"ref":"jos-8:30","status":"KRV_VERIFIED","exact_korean_token":"에발"},{"source":"1 Chr. 1:22","passage":"1ch-1","verse":22,"ref":"1ch-1:22","status":"KRV_VERIFIED","exact_korean_token":"에발"},{"source":"Gen. 10:28","passage":"gen-10","verse":28,"ref":"gen-10:28","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 36:23","passage":"gen-36","verse":23,"ref":"gen-36:23","status":"KRV_VERIFIED","exact_korean_token":"에발"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“돌 많은”이라는 뜻으로, 세겜 북쪽에 솟은 산이며 이스라엘 여섯 지파가 저주에 응답한 곳입니다."},{"candidate_id":"ATLBC-CAND-0110","name_en":"Geba","name_ko":"게바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GEBA","ko":"게바. Geba\n“언덕”이라는 뜻이다(삼하 5:25[대상 14:16에서는 “기브온”]; 왕하 23:8; 느 11:31). 베냐민의 레위 성읍이며(왕상 15:22; 삼상 13:16; 14:5, 흠정역에서는 잘못 “기브아”), 유다 북쪽 경계의 기브아 가까이에 있었다(사 10:29; 수 18:24, 28). “게바에서 브엘세바까지”는 “단에서 브엘세바까지”가 팔레스타인의 전체 길이를 말하듯 유다 왕국의 전체 범위를 나타냈다(왕하 23:8). 가바(수 18:24; 스 2:26; 느 7:30)로 비정되며 지금은 제브아로, 예루살렘 북쪽 약 5.5마일에 있다.","source_sha256":"4ef5bd9c1cfd5ee9565345f5d1f99b4fefffb1805d4f4ce418e7922394889d97","citation_candidates":[{"source":"2 Sam. 5:25","passage":"2sa-5","verse":25,"ref":"2sa-5:25","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Chr. 14:16","passage":"1ch-14","verse":16,"ref":"1ch-14:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 23:8","passage":"2ki-23","verse":8,"ref":"2ki-23:8","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Neh. 11:31","passage":"neh-11","verse":31,"ref":"neh-11:31","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Kings 15:22","passage":"1ki-15","verse":22,"ref":"1ki-15:22","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Sam. 13:16","passage":"1sa-13","verse":16,"ref":"1sa-13:16","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Isa. 10:29","passage":"isa-10","verse":29,"ref":"isa-10:29","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Josh. 18:24","passage":"jos-18","verse":24,"ref":"jos-18:24","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Ezra 2:26","passage":"ezr-2","verse":26,"ref":"ezr-2:26","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Neh. 7:30","passage":"neh-7","verse":30,"ref":"neh-7:30","status":"KRV_VERIFIED","exact_korean_token":"게바"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“언덕”이라는 뜻으로, 유다 북쪽 경계 기브아 가까이 있던 베냐민의 레위 성읍입니다."},{"candidate_id":"ATLBC-CAND-0114","name_en":"Makkedah","name_ko":"막게다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAKKEDAH","ko":"막게다. Makkedah\n“목자의 곳”이라는 뜻이다. 가나안 사람의 왕성 가운데 하나이며(수 12:16), 그 가까이에 이스라엘에 맞서 연합했던 다섯 왕이 피신한 굴이 있었다(10:10-29). 그들은 여호수아에게 죽임을 당했고 그는 이어 그들의 시신을 다섯 나무에 매달았다. 엘레우테로폴리스(베이트 지브린)에서 북서쪽으로 약 7마일, 낮은 언덕 위에 서 있는 지금의 수메일이라는 마을로 비정되었는데, 그곳에는 옛 유적과 큰 동굴이 있다. 그러나 팔레스타인 탐사 조사원들은 이를 얍네에서 3마일, 에그론 남서쪽 2.5마일의 엘무가르, 곧 “동굴들”로 비정했는데, 이는 “팔레스타인 평야에서 막게다로 가능한 모든 터 가운데 이곳에만 지금도 동굴이 있기” 때문이라고 한다. (아도니세덱 항목 참조.)","source_sha256":"3c1fc8ee232b837ea0997badc7457488177704562b173f964df048a02f588e1a","citation_candidates":[{"source":"Josh. 12:16","passage":"jos-12","verse":16,"ref":"jos-12:16","status":"KRV_VERIFIED","exact_korean_token":"막게다"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“목자의 곳”이라는 뜻의 가나안 왕성으로, 다섯 왕이 피신한 굴 가까이에 있었습니다."},{"candidate_id":"ATLBC-CAND-0116","name_en":"Moriah","name_ko":"모리아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MORIAH","ko":"모리아. Moriah\n“여호와께서 택하신 곳”이라는 뜻이다. 일부는 그리심 산을 가리킨다고 주장하지만 가장 유력하게는 이를 예루살렘의 언덕 가운데 하나로 보아야 한다. 여기에 솔로몬의 성전이 여부스 사람 오르난의 타작마당이었던 자리에 세워졌다(삼하 24:24-25; 대하 3:1). 보통 시온에 포함되며 그 북동쪽에 있었고 튀로포이온 골짜기로 갈라져 있었다. 이곳이 아브라함이 아들 이삭을 바치러 간 “모리아 땅”(창 22:2)이다. 성전 산의 가장 높은 곳, 곧 지금 이슬람의 쿠베트 엣삭라, 곧 “바위의 돔”으로 덮인 곳이 아라우나의 타작마당의 실제 자리일 것이라고 추측되어 왔다. 여기서도 아브라함에게서 천 년 뒤에 다윗이 제단을 쌓고 하나님께 제사를 드렸다. (예루살렘, 인구 조사 항목 참조.)","source_sha256":"3f7ebc7588a5d125a5a1d0d3d8f2b3103078fec64bdf30c92a91c8f11d4b414e","citation_candidates":[{"source":"2 Sam. 24:24","passage":"2sa-24","verse":24,"ref":"2sa-24:24","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Chr. 3:1","passage":"2ch-3","verse":1,"ref":"2ch-3:1","status":"KRV_VERIFIED","exact_korean_token":"모리아"},{"source":"Gen. 22:2","passage":"gen-22","verse":2,"ref":"gen-22:2","status":"KRV_VERIFIED","exact_korean_token":"모리아"}],"status":"READER_REFERENCE_ONLY","intro_ko":"“여호와께서 택하신 곳”이라는 뜻으로, 예루살렘의 한 언덕이며 솔로몬 성전이 세워진 곳입니다."},{"candidate_id":"ATLBC-CAND-0117","name_en":"Nob","name_ko":"놉","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-NOB","ko":"놉. Nob\n“높은 곳”이라는 뜻이다. 제사장들의 성읍으로, 다윗의 방랑 역사에서 처음 언급된다(삼상 21:1). 그때 장막이 이곳에 서 있었고 제사장 아히멜렉이 여기 살았다. (아히멜렉 항목 참조.) 사 10:28-32로 보아 예루살렘 가까이에 있었던 듯하다. 일부는 예루살렘 북동쪽 1.5마일의 엘이사위예로 비정했다. 그러나 사 10:28-32에 따르면 이곳은 게바 남쪽, 예루살렘으로 가는 길에 있어서 성이 보이는 곳이었다. 이 비정은 이 조건에 맞지 않으므로, 다른 이들(스탠리 학장 등)은 다윗이 압살롬을 피해 도망할 때 “하나님께 예배한” 곳(삼하 15:32)인 감람산 북쪽 봉우리라고 생각하거나, 더 개연성 있게(콘더) 예루살렘에서 북서쪽으로 약 5마일의 네비 삼윌에 있는 미스베(참조, 삿 20:1; 수 18:26; 삼상 7:16)와 같은 곳이라고 본다.\n\n다윗은 거룩한 진설병을 받고 에봇 뒤에서 꺼낸 골리앗의 칼을 허리에 찬 뒤 놉에서 도망하여 가드 왕 아기스의 궁정에서 피난처를 찾았으나 거기서 갇히게 되었다. (비교 시 34편과 56편 표제.)","source_sha256":"83acc41e03714316472aa654ec67481a6fa998656f7d79e1cdb867eb8ed0f358","citation_candidates":[{"source":"1 Sam. 21:1","passage":"1sa-21","verse":1,"ref":"1sa-21:1","status":"KRV_VERIFIED","exact_korean_token":"놉"},{"source":"Isa. 10:28-32","passage":"isa-10","verse":28,"ref":"isa-10:28","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 15:32","passage":"2sa-15","verse":32,"ref":"2sa-15:32","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 20:1","passage":"jdg-20","verse":1,"ref":"jdg-20:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 18:26","passage":"jos-18","verse":26,"ref":"jos-18:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 7:16","passage":"1sa-7","verse":16,"ref":"1sa-7:16","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“높은 곳”이라는 뜻의 제사장 성읍으로, 다윗이 방랑할 때 장막이 있던 곳이며 예루살렘 가까이에 있었습니다."},{"candidate_id":"ATLBC-CAND-0118","name_en":"Ophel","name_ko":"오벨","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-OPHEL","ko":"오벨. Ophel\n“언덕”, “둔덕”이라는 뜻이다. 성전 산 남쪽 비탈에서 튀로포이온 골짜기와 기드론 골짜기 사이에 뻗은 길고 좁고 둥근 곶이다(대하 27:3; 33:14; 느 3:26-27). 별도의 성벽으로 둘러싸여 있었고, 포로기 이후에는 느디님 사람이 차지했다. 이 성벽은 팔레스타인 탐사 기금의 기술자들이 성전 구역의 남동쪽 모서리에서 발견했다. 지금 지표 아래 4피트에 있다. 왕하 5:24에서 이 낱말은 “망대”(개정역 “언덕”)로 옮겨졌고, 아마 엘리사의 집 근처의 어떤 높은 곳을 가리킬 것이다.","source_sha256":"a4bacab73c1d9914964f0ebfceba24755e04fd75bbe68900bae3dfb731d0291e","citation_candidates":[{"source":"2 Chr. 27:3","passage":"2ch-27","verse":3,"ref":"2ch-27:3","status":"KRV_VERIFIED","exact_korean_token":"오벨"},{"source":"Neh. 3:26","passage":"neh-3","verse":26,"ref":"neh-3:26","status":"KRV_VERIFIED","exact_korean_token":"오벨"},{"source":"2 Kings 5:24","passage":"2ki-5","verse":24,"ref":"2ki-5:24","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"성전 산 남쪽 비탈의 길고 좁은 언덕으로, 포로기 이후 느디님 사람이 살았고 별도의 성벽으로 둘러싸여 있었습니다."},{"candidate_id":"ATLBC-CAND-0121","name_en":"Shunem","name_ko":"수넴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SHUNEM","ko":"수넴. Shunem\n“두 쉼터”라는 뜻이다. 잇사갈 지파의 작은 마을로, 이스르엘 북쪽, 길보아 산 남쪽에 있었다(수 19:18). 블레셋 사람이 사울을 치러 왔을 때 진을 친 곳이며(삼상 28:4), 엘리사가 그곳의 부유한 여인에게 환대를 받은 곳이다. 이 여인의 아들이 갑자기 죽자 그는 평야를 가로질러 20마일 떨어진 갈멜로 서둘러 가서 엘리사에게 알리고 그를 데리고 수넴으로 돌아왔다. 거기 “선지자의 방”에 죽은 아이가 누워 있었는데 엘리사가 들어가 문을 닫고 간절히 기도하니 아이가 살아났다(왕하 4:8-37). 이 여인은 후에 기근 때 블레셋 사람의 낮은 땅으로 물러났다가 몇 해 뒤 돌아와 보니 자기 집과 밭이 낯선 사람의 소유가 되어 있었다. 그가 사마리아의 왕에게 호소하여 다소 놀라운 방식으로 그것을 돌려받았다(비교 왕하 8:1-6).","source_sha256":"6789b1fc4990608074c4e6abb15047cd4b631d35540a6f2a2bc2b66afebfd266","citation_candidates":[{"source":"Josh. 19:18","passage":"jos-19","verse":18,"ref":"jos-19:18","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"1 Sam. 28:4","passage":"1sa-28","verse":4,"ref":"1sa-28:4","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"2 Kings 4:8-37","passage":"2ki-4","verse":8,"ref":"2ki-4:8","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"2 Kings 8:1-6","passage":"2ki-8","verse":1,"ref":"2ki-8:1","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY","intro_ko":"“두 쉼터”라는 뜻으로, 이스르엘 북쪽과 길보아 산 남쪽의 잇사갈 마을이며 엘리사가 환대받은 곳입니다."}];
